(window.YC_CS_BANK=window.YC_CS_BANK||[]).push({id:"cs-5996",module:"changshi",prompt:"西周实行的分封制中，受封的主要是：",options:["宗室子弟和功臣", "平民", "奴隶", "商人"],answer:0,explanation:"西周分封制将土地和人民分封给宗室子弟、功臣和先代贵族后裔，建立诸侯国，拱卫王室。"},{id:"cs-5997",module:"changshi",prompt:"商鞅变法发生在哪个国家？",options:["秦国", "齐国", "楚国", "魏国"],answer:0,explanation:"战国时期商鞅在秦国实行变法，奖励耕战、实行县制，使秦国成为战国后期最强大的国家。"},{id:"cs-5998",module:"changshi",prompt:"秦朝在地方上推行的行政制度是：",options:["分封制", "郡县制", "行省制", "州郡制"],answer:1,explanation:"秦朝废除分封制，在全国推行郡县制，郡守、县令由中央任命，加强了中央集权。"},{id:"cs-5999",module:"changshi",prompt:"汉武帝为加强中央集权设立的监察制度是：",options:["刺史制度", "都护府制度", "宣慰司制度", "行御史台制度"],answer:0,explanation:"汉武帝把全国分为十三州部，每州设刺史一名，负责监察地方官员，加强了中央对地方的控制。"},{id:"cs-6000",module:"changshi",prompt:"隋唐时期选拔官员的主要制度是：",options:["察举制", "九品中正制", "科举制", "征辟制"],answer:2,explanation:"隋唐时期实行科举制，通过考试选拔官员，打破了门第限制，是古代选官制度的重大变革。"},{id:"cs-6001",module:"changshi",prompt:"唐朝实行的赋税制度是：",options:["租庸调制", "两税法", "一条鞭法", "摊丁入亩"],answer:0,explanation:"唐朝前期实行租庸调制，以庸代役保证了农民的生产时间；780年杨炎建议实行两税法。"},{id:"cs-6002",module:"changshi",prompt:"北宋为加强中央集权采取的措施是：",options:["重文轻武", "重武轻文", "分封诸侯", "世袭罔替"],answer:0,explanation:"北宋为防止武将专权，实行重文轻武政策，文官担任要职，武将受到牵制。"},{id:"cs-6003",module:"changshi",prompt:"元朝在地方实行的行政制度是：",options:["郡县制", "行省制度", "州郡制", "分封制"],answer:1,explanation:"元朝实行行省制度，在地方设中书省派出机构，是我国省制的开端，对后世影响深远。"},{id:"cs-6004",module:"changshi",prompt:"明朝设立的特务机构是：",options:["锦衣卫和东厂", "军机处", "理藩院", "南书房"],answer:0,explanation:"明朝设立锦衣卫和东厂等特务机构，监视官民，加强了皇权，是君主专制强化的表现。"},{id:"cs-6005",module:"changshi",prompt:"清朝设立的军机处标志着：",options:["君主专制达到顶峰", "内阁制度确立", "三省六部制完善", "行省制度确立"],answer:0,explanation:"清朝雍正帝设立军机处，军国大事由皇帝一人裁决，标志着君主专制达到顶峰。"},{id:"cs-6006",module:"changshi",prompt:"我国古代'禅让制'出现在：",options:["夏朝以前", "夏朝", "商朝", "周朝"],answer:0,explanation:"禅让制是尧、舜、禹时期部落联盟首领的传位制度，首领让贤于有德之人，夏朝建立后变为世袭制。"},{id:"cs-6007",module:"changshi",prompt:"我国古代'世袭制'取代'禅让制'的标志是：",options:["禹传位于启", "汤灭夏", "武王伐纣", "平王东迁"],answer:0,explanation:"禹死后，其子启继承王位，世袭制取代禅让制，'公天下'变为'家天下'。"},{id:"cs-6008",module:"changshi",prompt:"我国古代'宗法制'的核心是：",options:["嫡长子继承制", "兄终弟及制", "选贤任能制", "禅让制"],answer:0,explanation:"宗法制以血缘关系为纽带，核心是嫡长子继承制，保证了贵族在政治上的垄断和特权。"},{id:"cs-6009",module:"changshi",prompt:"我国古代'礼乐制度'的制定者是：",options:["周公", "孔子", "老子", "管仲"],answer:0,explanation:"西周周公制定礼乐制度，规定了贵族在祭祀、宴饮、婚丧等场合的礼仪规范，维护了等级秩序。"},{id:"cs-6010",module:"changshi",prompt:"我国古代'井田制'的性质是：",options:["土地国有制", "土地私有制", "地主土地所有制", "农民土地所有制"],answer:0,explanation:"井田制是商周时期的土地国有制度，土地名义上归国家所有，由贵族经营，春秋后期逐渐瓦解。"},{id:"cs-6011",module:"changshi",prompt:"我国古代'初税亩'出现在：",options:["鲁国", "齐国", "晋国", "楚国"],answer:0,explanation:"公元前594年鲁国实行'初税亩'，按亩征税，承认土地私有，是古代赋税制度的重大变革。"},{id:"cs-6012",module:"changshi",prompt:"我国古代'编户齐民'制度出现在：",options:["秦朝", "汉朝", "唐朝", "宋朝"],answer:1,explanation:"汉朝实行编户齐民制度，把百姓编入户籍，作为征收赋税、征发徭役和兵役的依据。"},{id:"cs-6013",module:"changshi",prompt:"我国古代'均田制'开始于：",options:["北魏", "隋朝", "唐朝", "宋朝"],answer:0,explanation:"北魏孝文帝推行均田制，将国家掌握的土地分配给农民，隋唐沿用，唐中期瓦解。"},{id:"cs-6014",module:"changshi",prompt:"我国古代'租庸调制'中的'庸'指的是：",options:["以绢或布代替徭役", "缴纳粮食", "缴纳户税", "缴纳地租"],answer:0,explanation:"租庸调制中的'庸'指农民可以纳绢或布代替徭役，保证了农民的生产时间。"},{id:"cs-6015",module:"changshi",prompt:"我国古代'两税法'的征税标准是：",options:["人丁和资产", "只按人丁", "只按资产", "按土地面积"],answer:0,explanation:"780年唐朝宰相杨炎建议实行两税法，按人丁和资产缴纳户税，按田亩缴纳地税，一年分夏秋两次征税。"},{id:"cs-6016",module:"changshi",prompt:"我国古代'方田均税法'的推行者是：",options:["王安石", "张居正", "商鞅", "管仲"],answer:0,explanation:"北宋王安石变法推行方田均税法，清丈土地、按土地多少和肥瘠收税，增加了财政收入。"},{id:"cs-6017",module:"changshi",prompt:"我国古代'一条鞭法'的征税方式是：",options:["赋役合并折银征收", "按人丁征税", "按户征税", "按土地征税"],answer:0,explanation:"明朝张居正推行一条鞭法，将赋役合并、折银征收，简化了税制，促进了商品经济发展。"},{id:"cs-6018",module:"changshi",prompt:"我国古代'摊丁入亩'的推行者是：",options:["康熙帝", "雍正帝", "乾隆帝", "嘉庆帝"],answer:1,explanation:"清朝雍正帝推行摊丁入亩，将丁银摊入田赋一并征收，废除了人头税，减轻了无地农民的负担。"},{id:"cs-6019",module:"changshi",prompt:"我国古代'科举制'正式确立的标志是：",options:["隋炀帝设进士科", "唐朝设明经科", "武则天创殿试", "宋朝设糊名法"],answer:0,explanation:"隋炀帝时设进士科，标志着科举制正式确立；唐朝进一步完善，武则天首创殿试和武举。"},{id:"cs-6020",module:"changshi",prompt:"我国古代'三省六部制'中负责执行政令的是：",options:["中书省", "门下省", "尚书省", "御史台"],answer:2,explanation:"三省六部制中，中书省起草诏令，门下省审核，尚书省执行，下设吏、户、礼、兵、刑、工六部。"},{id:"cs-6021",module:"changshi",prompt:"我国古代'内阁制度'确立于：",options:["明太祖时期", "明成祖时期", "明仁宗时期", "明宣宗时期"],answer:1,explanation:"明成祖设内阁，作为皇帝的顾问机构，后来权力逐渐增大，但始终不是法定中央机构。"},{id:"cs-6022",module:"changshi",prompt:"我国古代'八旗制度'的创建者是：",options:["努尔哈赤", "皇太极", "顺治帝", "康熙帝"],answer:0,explanation:"努尔哈赤创建八旗制度，将女真各部编入八旗，兵民合一，是清朝的立国之本。"},{id:"cs-6023",module:"changshi",prompt:"我国古代'理藩院'的职能是：",options:["管理少数民族事务", "管理外交事务", "管理财政事务", "管理司法事务"],answer:0,explanation:"清朝设立理藩院，负责管理蒙古、西藏、新疆等少数民族事务，是中央管理民族事务的机构。"},{id:"cs-6024",module:"changshi",prompt:"我国古代'驻藏大臣'设立于：",options:["顺治时期", "康熙时期", "雍正时期", "乾隆时期"],answer:2,explanation:"1727年雍正帝设驻藏大臣，代表中央与达赖、班禅共同管理西藏事务，加强了中央对西藏的管辖。"},{id:"cs-6025",module:"changshi",prompt:"我国古代'金瓶掣签'制度确立于：",options:["康熙时期", "雍正时期", "乾隆时期", "嘉庆时期"],answer:2,explanation:"乾隆时期确立金瓶掣签制度，规定达赖、班禅等大活佛转世须经金瓶掣签认定，加强了中央对西藏宗教的管理。"},{id:"cs-6026",module:"changshi",prompt:"我国东部地区的主要气候类型是：",options:["温带季风气候", "地中海气候", "温带海洋性气候", "热带沙漠气候"],answer:0,explanation:"我国东部地区受海陆热力性质差异影响，形成典型的季风气候，自南向北依次为热带、亚热带、温带季风气候。"},{id:"cs-6027",module:"changshi",prompt:"我国西北地区的主要气候类型是：",options:["温带季风气候", "温带大陆性气候", "高原山地气候", "热带季风气候"],answer:1,explanation:"我国西北地区深居内陆、远离海洋，降水稀少，形成温带大陆性气候，气温日较差和年较差大。"},{id:"cs-6028",module:"changshi",prompt:"我国青藏地区的主要气候类型是：",options:["温带季风气候", "高原山地气候", "温带大陆性气候", "亚热带季风气候"],answer:1,explanation:"青藏地区平均海拔4000米以上，形成独特的高原山地气候，气温低、日照强、昼夜温差大。"},{id:"cs-6029",module:"changshi",prompt:"我国降水分布的总体规律是：",options:["从东南沿海向西北内陆递减", "从西北向东南递减", "从北向南递减", "从西向东递减"],answer:0,explanation:"我国降水受夏季风影响，从东南沿海向西北内陆递减，东南沿海降水超过1600毫米，西北内陆不足200毫米。"},{id:"cs-6030",module:"changshi",prompt:"我国夏季风的来源是：",options:["西伯利亚和蒙古", "太平洋和印度洋", "大西洋", "北冰洋"],answer:1,explanation:"我国夏季风来自太平洋的东南季风和印度洋的西南季风，温暖湿润，带来丰沛降水。"},{id:"cs-6031",module:"changshi",prompt:"我国冬季风的来源是：",options:["太平洋和印度洋", "西伯利亚和蒙古", "大西洋", "北冰洋"],answer:1,explanation:"我国冬季风来自西伯利亚和蒙古一带，寒冷干燥，加剧了北方的寒冷，使南北温差增大。"},{id:"cs-6032",module:"changshi",prompt:"我国雨季开始最早、结束最晚的地区是：",options:["华南地区", "长江中下游地区", "华北地区", "东北地区"],answer:0,explanation:"我国雨季由南向北推进，华南地区雨季开始最早（4月）、结束最晚（10月），雨季最长。"},{id:"cs-6033",module:"changshi",prompt:"我国长江中下游地区'梅雨'天气出现在：",options:["6月中旬至7月上旬", "7月中旬至8月上旬", "8月中旬至9月上旬", "4月中旬至5月上旬"],answer:0,explanation:"6月中旬至7月上旬，冷暖气团在长江中下游地区交锋，形成持续阴雨的'梅雨'天气。"},{id:"cs-6034",module:"changshi",prompt:"我国'伏旱'天气主要出现在：",options:["长江中下游地区", "华北地区", "东北地区", "西南地区"],answer:0,explanation:"7、8月份长江中下游地区受副热带高压控制，盛行下沉气流，天气晴朗少雨，形成'伏旱'。"},{id:"cs-6035",module:"changshi",prompt:"我国'春旱'最严重的地区是：",options:["华北地区", "东北地区", "长江中下游地区", "华南地区"],answer:0,explanation:"华北地区春季气温回升快、蒸发旺盛，但雨季未到、降水少，春旱严重，影响春耕生产。"},{id:"cs-6036",module:"changshi",prompt:"我国最大的冰川分布区是：",options:["青藏高原", "天山", "昆仑山", "阿尔泰山"],answer:0,explanation:"青藏高原是我国最大的冰川分布区，冰川储量约占全国的五分之四，是亚洲重要水源地。"},{id:"cs-6037",module:"changshi",prompt:"我国含沙量最大的河流是：",options:["黄河", "长江", "珠江", "辽河"],answer:0,explanation:"黄河中游流经黄土高原，携带大量泥沙，是世界上含沙量最大的河流，年均输沙量约16亿吨。"},{id:"cs-6038",module:"changshi",prompt:"我国古代建筑中'榫卯结构'的主要优点是：",options:["不用钉子即可牢固连接", "节省木材", "施工速度快", "防水防火"],answer:0,explanation:"榫卯结构通过木构件凹凸咬合连接，不用钉子即可牢固连接，具有抗震性能好、可拆卸等优点。"},{id:"cs-6039",module:"changshi",prompt:"我国古代建筑'斗拱'的主要作用是：",options:["承重和装饰", "防潮", "采光", "通风"],answer:0,explanation:"斗拱位于柱顶、额枋与屋顶之间，起承重作用，将屋顶荷载传递到立柱，同时具有装饰功能。"},{id:"cs-6040",module:"changshi",prompt:"我国古代建筑'飞檐'的主要功能是：",options:["排水和采光", "承重", "防震", "保温"],answer:0,explanation:"飞檐使屋顶坡度变缓、檐口上翘，有利于排水和室内采光，同时具有优美的造型。"},{id:"cs-6041",module:"changshi",prompt:"我国古代建筑'影壁'的主要功能是：",options:["遮挡视线", "承重", "防潮", "采光"],answer:0,explanation:"影壁（照壁）设在大门内或外，用于遮挡视线、保护隐私，同时具有装饰作用。"},{id:"cs-6042",module:"changshi",prompt:"我国古代建筑'四合院'的布局特点是：",options:["中轴对称、封闭围合", "自由布局", "开放式", "依山就势"],answer:0,explanation:"四合院以中轴对称布局，由正房、厢房、倒座房围合而成，体现了封建礼制和家族观念。"},{id:"cs-6043",module:"changshi",prompt:"我国古代建筑'窑洞'主要分布在：",options:["黄土高原", "内蒙古高原", "青藏高原", "云贵高原"],answer:0,explanation:"窑洞主要分布在黄土高原地区，利用黄土的直立性挖掘而成，冬暖夏凉、节省土地。"},{id:"cs-6044",module:"changshi",prompt:"我国古代建筑'吊脚楼'主要分布在：",options:["西南山区", "东北地区", "华北平原", "西北地区"],answer:0,explanation:"吊脚楼主要分布在西南山区（如贵州、湖南西部），依山而建，通风防潮，适应山地地形。"},{id:"cs-6045",module:"changshi",prompt:"我国古代建筑'蒙古包'的主要特点是：",options:["可拆卸移动", "固定建筑", "砖石结构", "多层建筑"],answer:0,explanation:"蒙古包是蒙古族牧民的传统住所，用毛毡覆盖、木架支撑，可拆卸移动，适应游牧生活。"},{id:"cs-6046",module:"changshi",prompt:"我国古代建筑'客家土楼'的主要功能是：",options:["防御和聚居", "仓储", "祭祀", "观景"],answer:0,explanation:"客家土楼是福建、广东等地客家人的聚居建筑，具有防御功能，体现了聚族而居的传统。"},{id:"cs-6047",module:"changshi",prompt:"我国古代建筑'布达拉宫'位于：",options:["西藏拉萨", "青海西宁", "四川成都", "甘肃兰州"],answer:0,explanation:"布达拉宫位于西藏拉萨红山上，是藏传佛教的象征，1994年被列入世界文化遗产。"},{id:"cs-6048",module:"changshi",prompt:"我国古代建筑'赵州桥'的设计者是：",options:["李春", "鲁班", "李诫", "喻皓"],answer:0,explanation:"隋代工匠李春设计建造赵州桥，是世界上现存最古老、保存最完整的敞肩石拱桥。"},{id:"cs-6049",module:"changshi",prompt:"我国古代建筑'应县木塔'的结构特点是：",options:["全木结构", "砖木混合结构", "砖石结构", "夯土结构"],answer:0,explanation:"应县木塔建于辽代，高67.31米，是我国现存最高最古老的纯木结构楼阁式建筑。"},{id:"cs-6050",module:"changshi",prompt:"我国古代建筑'故宫'的屋顶形式中等级最高的是：",options:["庑殿顶", "歇山顶", "悬山顶", "硬山顶"],answer:0,explanation:"庑殿顶是古代建筑中等级最高的屋顶形式，故宫太和殿为重檐庑殿顶，是最高等级。"},{id:"cs-6051",module:"changshi",prompt:"我国古代建筑'天坛祈年殿'的用途是：",options:["祭天", "祭祖", "朝政", "居住"],answer:0,explanation:"天坛祈年殿是明清皇帝祭天祈谷的场所，三重檐攒尖顶，是古代祭祀建筑的杰作。"},{id:"cs-6052",module:"changshi",prompt:"我国古代建筑'颐和园'的前身是：",options:["清漪园", "圆明园", "畅春园", "静宜园"],answer:0,explanation:"颐和园前身是清漪园，1888年慈禧太后挪用海军经费重修，改称颐和园。"},{id:"cs-6053",module:"changshi",prompt:"我国古代建筑'拙政园'的造园手法是：",options:["借景", "对景", "框景", "以上都是"],answer:3,explanation:"拙政园运用借景、对景、框景等多种造园手法，以小见大，是江南私家园林的代表作。"},{id:"cs-6054",module:"changshi",prompt:"我国古代建筑'长城'的起点和终点是：",options:["山海关至嘉峪关", "虎山至嘉峪关", "山海关至玉门关", "居庸关至雁门关"],answer:1,explanation:"明长城东起辽宁虎山，西至甘肃嘉峪关，全长8800多公里，是我国古代最伟大的防御工程。"},{id:"cs-6055",module:"changshi",prompt:"我国古代建筑'都江堰'的作用是：",options:["防洪灌溉", "航运", "发电", "养殖"],answer:0,explanation:"都江堰是战国时期李冰父子修建的水利工程，具有防洪、灌溉等功能，使成都平原成为'天府之国'。"},{id:"cs-6056",module:"changshi",prompt:"我国古代建筑'灵渠'沟通了哪两大水系？",options:["长江和珠江", "黄河和淮河", "长江和黄河", "淮河和济水"],answer:0,explanation:"灵渠位于广西兴安，秦代修建，沟通了长江水系的湘江和珠江水系的漓江，是世界上最古老的运河之一。"},{id:"cs-6057",module:"changshi",prompt:"我国古代建筑'京杭大运河'开凿于：",options:["隋朝", "唐朝", "元朝", "明朝"],answer:0,explanation:"京杭大运河始建于春秋时期，隋朝大规模扩建，元朝裁弯取直，形成今天的京杭大运河。"},{id:"cs-6058",module:"changshi",prompt:"我国古代雕塑'秦始皇陵兵马俑'被誉为：",options:["世界第八大奇迹", "世界七大奇迹", "东方明珠", "东方金字塔"],answer:0,explanation:"秦始皇陵兵马俑1974年发现，被誉为'世界第八大奇迹'，1987年被列入世界文化遗产。"},{id:"cs-6059",module:"changshi",prompt:"我国古代雕塑'乐山大佛'开凿于：",options:["唐代", "宋代", "明代", "清代"],answer:0,explanation:"乐山大佛开凿于唐代，通高71米，是我国最大的古代石刻坐佛，依凌云山栖鸾峰断崖凿成。"},{id:"cs-6060",module:"changshi",prompt:"我国古代绘画'清明上河图'的作者是：",options:["张择端", "王希孟", "黄公望", "范宽"],answer:0,explanation:"北宋张择端的《清明上河图》描绘了汴京（开封）的城市生活，是风俗画的代表作。"},{id:"cs-6061",module:"changshi",prompt:"我国古代绘画'千里江山图'的作者是：",options:["王希孟", "张择端", "黄公望", "范宽"],answer:0,explanation:"北宋王希孟18岁创作《千里江山图》，以青绿山水描绘千里江山，是青绿山水画的巅峰之作。"},{id:"cs-6062",module:"changshi",prompt:"我国古代绘画'富春山居图'的作者是：",options:["黄公望", "王蒙", "倪瓒", "吴镇"],answer:0,explanation:"元代黄公望的《富春山居图》以水墨描绘富春江两岸秋景，是'元四家'之首的代表作。"},{id:"cs-6063",module:"changshi",prompt:"我国古代书法'兰亭序'的作者是：",options:["王羲之", "颜真卿", "柳公权", "欧阳询"],answer:0,explanation:"东晋王羲之的《兰亭序》被誉为'天下第一行书'，其书法兼善众体，被尊为'书圣'。"},{id:"cs-6064",module:"changshi",prompt:"我国古代书法'颜勤礼碑'的作者是：",options:["颜真卿", "柳公权", "欧阳询", "赵孟頫"],answer:0,explanation:"唐代颜真卿的《颜勤礼碑》是楷书代表作，其书法雄浑大气，被称为'颜体'。"},{id:"cs-6065",module:"changshi",prompt:"我国古代书法'玄秘塔碑'的作者是：",options:["柳公权", "颜真卿", "欧阳询", "赵孟頫"],answer:0,explanation:"唐代柳公权的《玄秘塔碑》是楷书代表作，其书法骨力劲健，被称为'柳体'，与颜体并称'颜筋柳骨'。"},{id:"cs-6066",module:"changshi",prompt:"我国古代书法'九成宫醴泉铭'的作者是：",options:["欧阳询", "颜真卿", "柳公权", "赵孟頫"],answer:0,explanation:"唐代欧阳询的《九成宫醴泉铭》是楷书代表作，其书法险峻严谨，被称为'欧体'。"},{id:"cs-6067",module:"changshi",prompt:"我国古代书法'胆巴碑'的作者是：",options:["赵孟頫", "欧阳询", "颜真卿", "柳公权"],answer:0,explanation:"元代赵孟頫的《胆巴碑》是楷书代表作，其书法圆润秀美，被称为'赵体'，与欧、颜、柳并称楷书四大家。"},{id:"cs-6068",module:"changshi",prompt:"成年人每日推荐饮水量约为：",options:["500—800毫升", "1000—1200毫升", "1500—1700毫升", "2500—3000毫升"],answer:2,explanation:"成年人每日推荐饮水量约1500—1700毫升（7—8杯），包括饮水和食物中的水分，过量或不足都不利健康。"},{id:"cs-6069",module:"changshi",prompt:"成年人每日推荐食盐摄入量不超过：",options:["3克", "5克", "8克", "10克"],answer:1,explanation:"世界卫生组织和我国膳食指南建议成年人每日食盐摄入量不超过5克，过量摄入会增加高血压风险。"},{id:"cs-6070",module:"changshi",prompt:"成年人每日推荐添加糖摄入量不超过：",options:["10克", "25克", "50克", "100克"],answer:1,explanation:"世界卫生组织建议成年人每日添加糖摄入量不超过25克，过量摄入会增加肥胖和糖尿病风险。"},{id:"cs-6071",module:"changshi",prompt:"成年人每日推荐食用油摄入量为：",options:["10—15克", "25—30克", "40—50克", "60—80克"],answer:1,explanation:"我国膳食指南建议成年人每日食用油摄入量为25—30克，过量摄入会增加肥胖和心血管疾病风险。"},{id:"cs-6072",module:"changshi",prompt:"成年人每日推荐蔬菜摄入量为：",options:["100—200克", "300—500克", "600—800克", "1000克以上"],answer:1,explanation:"我国膳食指南建议成年人每日蔬菜摄入量为300—500克，深色蔬菜应占一半以上。"},{id:"cs-6073",module:"changshi",prompt:"成年人每日推荐水果摄入量为：",options:["50—100克", "200—350克", "500—800克", "1000克以上"],answer:1,explanation:"我国膳食指南建议成年人每日水果摄入量为200—350克，果汁不能代替鲜果。"},{id:"cs-6074",module:"changshi",prompt:"成年人每周推荐运动时长为：",options:["30分钟", "75分钟", "150分钟", "300分钟"],answer:2,explanation:"世界卫生组织建议成年人每周至少进行150分钟中等强度有氧运动，或75分钟高强度运动。"},{id:"cs-6075",module:"changshi",prompt:"成年人每日推荐睡眠时长为：",options:["5—6小时", "7—9小时", "10—12小时", "12小时以上"],answer:1,explanation:"成年人每日推荐睡眠时长为7—9小时，长期睡眠不足会增加心血管疾病和肥胖风险。"},{id:"cs-6076",module:"changshi",prompt:"成年人正常血压范围为：",options:["收缩压90—139mmHg，舒张压60—89mmHg", "收缩压140—159mmHg，舒张压90—99mmHg", "收缩压160mmHg以上，舒张压100mmHg以上", "收缩压80mmHg以下，舒张压50mmHg以下"],answer:0,explanation:"成年人正常血压范围为收缩压90—139mmHg、舒张压60—89mmHg；≥140/90mmHg为高血压。"},{id:"cs-6077",module:"changshi",prompt:"成年人正常空腹血糖范围为：",options:["3.9—6.1mmol/L", "6.1—7.0mmol/L", "7.0—11.1mmol/L", "11.1mmol/L以上"],answer:0,explanation:"成年人正常空腹血糖范围为3.9—6.1mmol/L；≥7.0mmol/L考虑糖尿病，需复查确认。"},{id:"cs-6078",module:"changshi",prompt:"成年人正常体重指数（BMI）范围为：",options:["18.5—23.9", "24—27.9", "28—32.9", "33以上"],answer:0,explanation:"我国成年人正常BMI范围为18.5—23.9；24—27.9为超重，≥28为肥胖。"},{id:"cs-6079",module:"changshi",prompt:"成年人每日推荐蛋白质摄入量约为每公斤体重：",options:["0.5克", "0.8—1.0克", "1.5—2.0克", "2.5克以上"],answer:1,explanation:"成年人每日推荐蛋白质摄入量约为每公斤体重0.8—1.0克，运动员和孕妇可适当增加。"},{id:"cs-6080",module:"changshi",prompt:"成年人每日推荐钙摄入量约为：",options:["400毫克", "800毫克", "1500毫克", "2000毫克"],answer:1,explanation:"我国膳食指南建议成年人每日钙摄入量为800毫克，50岁以上人群可增至1000毫克。"},{id:"cs-6081",module:"changshi",prompt:"成年人每日推荐铁摄入量约为：",options:["5毫克", "12—20毫克", "50毫克", "100毫克"],answer:1,explanation:"我国膳食指南建议成年男性每日铁摄入量为12毫克，女性为20毫克，缺铁会导致贫血。"},{id:"cs-6082",module:"changshi",prompt:"成年人每日推荐膳食纤维摄入量约为：",options:["5—10克", "25—30克", "50—60克", "100克以上"],answer:1,explanation:"我国膳食指南建议成年人每日膳食纤维摄入量为25—30克，有助于肠道健康和控制血糖。"},{id:"cs-6083",module:"changshi",prompt:"成年人每日推荐胆固醇摄入量不超过：",options:["100毫克", "300毫克", "500毫克", "1000毫克"],answer:1,explanation:"我国膳食指南建议成年人每日胆固醇摄入量不超过300毫克，过量摄入会增加心血管疾病风险。"},{id:"cs-6084",module:"changshi",prompt:"成年人每日推荐维生素C摄入量约为：",options:["10毫克", "100毫克", "500毫克", "1000毫克"],answer:1,explanation:"我国膳食指南建议成年人每日维生素C摄入量为100毫克，可从新鲜蔬菜水果中获取。"},{id:"cs-6085",module:"changshi",prompt:"成年人每日推荐维生素D摄入量约为：",options:["100国际单位", "400国际单位", "1000国际单位", "2000国际单位"],answer:1,explanation:"我国膳食指南建议成年人每日维生素D摄入量为400国际单位（10微克），可通过晒太阳和食物获取。"},{id:"cs-6086",module:"changshi",prompt:"成年人每日推荐维生素A摄入量约为：",options:["100微克", "800微克", "3000微克", "5000微克"],answer:1,explanation:"我国膳食指南建议成年男性每日维生素A摄入量为800微克视黄醇当量，女性为700微克。"},{id:"cs-6087",module:"changshi",prompt:"成年人每日推荐维生素B1摄入量约为：",options:["0.5毫克", "1.4毫克", "5毫克", "10毫克"],answer:1,explanation:"我国膳食指南建议成年人每日维生素B1摄入量为1.4毫克，缺乏会导致脚气病。"},{id:"cs-6088",module:"changshi",prompt:"成年人每日推荐维生素B2摄入量约为：",options:["0.5毫克", "1.4毫克", "5毫克", "10毫克"],answer:1,explanation:"我国膳食指南建议成年人每日维生素B2摄入量为1.4毫克，缺乏会导致口角炎、舌炎。"},{id:"cs-6089",module:"changshi",prompt:"成年人每日推荐维生素E摄入量约为：",options:["5毫克", "14毫克", "50毫克", "100毫克"],answer:1,explanation:"我国膳食指南建议成年人每日维生素E摄入量为14毫克，具有抗氧化作用。"},{id:"cs-6090",module:"changshi",prompt:"成年人每日推荐锌摄入量约为：",options:["5毫克", "12.5毫克", "50毫克", "100毫克"],answer:1,explanation:"我国膳食指南建议成年男性每日锌摄入量为12.5毫克，女性为7.5毫克，缺锌会影响免疫力。"},{id:"cs-6091",module:"changshi",prompt:"成年人每日推荐硒摄入量约为：",options:["20微克", "60微克", "200微克", "400微克"],answer:1,explanation:"我国膳食指南建议成年人每日硒摄入量为60微克，具有抗氧化作用，过量会中毒。"},{id:"cs-6092",module:"changshi",prompt:"成年人每日推荐碘摄入量约为：",options:["50微克", "120微克", "500微克", "1000微克"],answer:1,explanation:"我国膳食指南建议成年人每日碘摄入量为120微克，缺碘会导致甲状腺肿大。"},{id:"cs-6093",module:"changshi",prompt:"成年人每日推荐钾摄入量约为：",options:["500毫克", "2000毫克", "5000毫克", "10000毫克"],answer:1,explanation:"我国膳食指南建议成年人每日钾摄入量为2000毫克，有助于控制血压。"},{id:"cs-6094",module:"changshi",prompt:"成年人每日推荐钠摄入量不超过：",options:["1000毫克", "2000毫克", "5000毫克", "10000毫克"],answer:1,explanation:"我国膳食指南建议成年人每日钠摄入量不超过2000毫克（约5克食盐），过量会增加高血压风险。"},{id:"cs-6095",module:"changshi",prompt:"成年人每日推荐磷摄入量约为：",options:["200毫克", "720毫克", "2000毫克", "5000毫克"],answer:1,explanation:"我国膳食指南建议成年人每日磷摄入量为720毫克，与钙的比例以1:1—1.5:1为宜。"},{id:"cs-6096",module:"changshi",prompt:"成年人每日推荐镁摄入量约为：",options:["100毫克", "330毫克", "1000毫克", "2000毫克"],answer:1,explanation:"我国膳食指南建议成年人每日镁摄入量为330毫克，有助于神经和肌肉功能。"},{id:"cs-6097",module:"changshi",prompt:"成年人每日推荐铜摄入量约为：",options:["0.5毫克", "0.8毫克", "5毫克", "10毫克"],answer:1,explanation:"我国膳食指南建议成年人每日铜摄入量为0.8毫克，缺铜会影响铁的代谢。"});
(window.YC_CS_BANK=window.YC_CS_BANK||[]).push({id:"cs-6098",module:"changshi",prompt:"《堂吉诃德》的作者是：",options:["塞万提斯", "拉伯雷", "薄伽丘", "莎士比亚"],answer:0,explanation:"西班牙作家塞万提斯的《堂吉诃德》是欧洲第一部现实主义小说，讽刺了骑士文学。"},{id:"cs-6099",module:"changshi",prompt:"《浮士德》的作者是：",options:["歌德", "席勒", "海涅", "拜伦"],answer:0,explanation:"德国作家歌德的《浮士德》是德国文学的巅峰之作，讲述浮士德与魔鬼的契约故事。"},{id:"cs-6100",module:"changshi",prompt:"《悲惨世界》的作者是：",options:["雨果", "巴尔扎克", "大仲马", "莫泊桑"],answer:0,explanation:"法国作家雨果的《悲惨世界》讲述冉·阿让的故事，是浪漫主义文学的代表作。"},{id:"cs-6101",module:"changshi",prompt:"《战争与和平》的作者是：",options:["托尔斯泰", "陀思妥耶夫斯基", "普希金", "果戈理"],answer:0,explanation:"俄国作家托尔斯泰的《战争与和平》以拿破仑战争为背景，是俄国文学的巅峰之作。"},{id:"cs-6102",module:"changshi",prompt:"《罪与罚》的作者是：",options:["陀思妥耶夫斯基", "托尔斯泰", "普希金", "果戈理"],answer:0,explanation:"俄国作家陀思妥耶夫斯基的《罪与罚》讲述大学生拉斯柯尔尼科夫的犯罪与救赎，是心理小说的杰作。"},{id:"cs-6103",module:"changshi",prompt:"《老人与海》的作者是：",options:["海明威", "福克纳", "马克·吐温", "杰克·伦敦"],answer:0,explanation:"美国作家海明威的《老人与海》讲述老渔夫圣地亚哥的故事，1954年获诺贝尔文学奖。"},{id:"cs-6104",module:"changshi",prompt:"《傲慢与偏见》的作者是：",options:["简·奥斯汀", "勃朗特姐妹", "狄更斯", "哈代"],answer:0,explanation:"英国作家简·奥斯汀的《傲慢与偏见》以乡绅家庭生活为背景，是英国文学的经典之作。"},{id:"cs-6105",module:"changshi",prompt:"《简·爱》的作者是：",options:["夏洛蒂·勃朗特", "艾米莉·勃朗特", "狄更斯", "哈代"],answer:0,explanation:"英国作家夏洛蒂·勃朗特的《简·爱》讲述孤女简·爱的成长故事，是女性文学的代表作。"},{id:"cs-6106",module:"changshi",prompt:"《呼啸山庄》的作者是：",options:["艾米莉·勃朗特", "夏洛蒂·勃朗特", "狄更斯", "哈代"],answer:0,explanation:"英国作家艾米莉·勃朗特的《呼啸山庄》讲述希斯克利夫的复仇故事，是哥特式小说的代表作。"},{id:"cs-6107",module:"changshi",prompt:"《双城记》的作者是：",options:["狄更斯", "哈代", "萨克雷", "勃朗特"],answer:0,explanation:"英国作家狄更斯的《双城记》以法国大革命为背景，开篇'这是最好的时代，也是最坏的时代'广为流传。"},{id:"cs-6108",module:"changshi",prompt:"《红与黑》的作者是：",options:["司汤达", "巴尔扎克", "福楼拜", "左拉"],answer:0,explanation:"法国作家司汤达的《红与黑》讲述于连的奋斗故事，是批判现实主义文学的奠基之作。"},{id:"cs-6109",module:"changshi",prompt:"《包法利夫人》的作者是：",options:["福楼拜", "司汤达", "巴尔扎克", "左拉"],answer:0,explanation:"法国作家福楼拜的《包法利夫人》讲述爱玛的悲剧，是现实主义文学的典范。"},{id:"cs-6110",module:"changshi",prompt:"《变形记》的作者是：",options:["卡夫卡", "乔伊斯", "普鲁斯特", "贝克特"],answer:0,explanation:"奥地利作家卡夫卡的《变形记》讲述格里高尔变成甲虫的故事，是现代主义文学的代表作。"},{id:"cs-6111",module:"changshi",prompt:"《尤利西斯》的作者是：",options:["乔伊斯", "卡夫卡", "普鲁斯特", "贝克特"],answer:0,explanation:"爱尔兰作家乔伊斯的《尤利西斯》以意识流手法描写都柏林一天的生活，是现代主义文学的巅峰。"},{id:"cs-6112",module:"changshi",prompt:"《追忆似水年华》的作者是：",options:["普鲁斯特", "乔伊斯", "卡夫卡", "贝克特"],answer:0,explanation:"法国作家普鲁斯特的《追忆似水年华》以意识流手法回忆往事，共7卷，是20世纪文学的巨著。"},{id:"cs-6113",module:"changshi",prompt:"《等待戈多》的作者是：",options:["贝克特", "尤内斯库", "卡夫卡", "乔伊斯"],answer:0,explanation:"爱尔兰作家贝克特的《等待戈多》是荒诞派戏剧的代表作，1969年获诺贝尔文学奖。"},{id:"cs-6114",module:"changshi",prompt:"《挪威的森林》的作者是：",options:["村上春树", "川端康成", "三岛由纪夫", "大江健三郎"],answer:0,explanation:"日本作家村上春树的《挪威的森林》以青春爱情为主题，是全球畅销小说。"},{id:"cs-6115",module:"changshi",prompt:"《吉檀迦利》的作者是：",options:["泰戈尔", "普列姆昌德", "奈保尔", "拉什迪"],answer:0,explanation:"印度诗人泰戈尔的《吉檀迦利》是宗教抒情诗集，1913年获诺贝尔文学奖，是亚洲首位获奖者。"},{id:"cs-6116",module:"changshi",prompt:"《一千零一夜》是哪个地区的民间故事集？",options:["阿拉伯", "波斯", "印度", "埃及"],answer:0,explanation:"《一千零一夜》是阿拉伯民间故事集，又称《天方夜谭》，收录了《阿里巴巴与四十大盗》等故事。"},{id:"cs-6117",module:"changshi",prompt:"《伊索寓言》产生于：",options:["古希腊", "古罗马", "古埃及", "古印度"],answer:0,explanation:"《伊索寓言》是古希腊寓言集，收录了《龟兔赛跑》《狼和小羊》等经典寓言。"},{id:"cs-6118",module:"changshi",prompt:"《荷马史诗》包括《伊利亚特》和：",options:["《奥德赛》", "《埃涅阿斯纪》", "《神谱》", "《工作与时日》"],answer:0,explanation:"《荷马史诗》包括《伊利亚特》和《奥德赛》，相传为盲诗人荷马所作，是西方文学的源头。"},{id:"cs-6119",module:"changshi",prompt:"《被缚的普罗米修斯》的作者是：",options:["埃斯库罗斯", "索福克勒斯", "欧里庇得斯", "阿里斯托芬"],answer:0,explanation:"古希腊悲剧家埃斯库罗斯的《被缚的普罗米修斯》讲述普罗米修斯盗火的故事，是希腊悲剧的代表作。"},{id:"cs-6120",module:"changshi",prompt:"《俄狄浦斯王》的作者是：",options:["索福克勒斯", "埃斯库罗斯", "欧里庇得斯", "阿里斯托芬"],answer:0,explanation:"古希腊悲剧家索福克勒斯的《俄狄浦斯王》被誉为'命运悲剧'的典范。"},{id:"cs-6121",module:"changshi",prompt:"《美狄亚》的作者是：",options:["欧里庇得斯", "索福克勒斯", "埃斯库罗斯", "阿里斯托芬"],answer:0,explanation:"古希腊悲剧家欧里庇得斯的《美狄亚》讲述美狄亚的复仇故事，是'心理悲剧'的开端。"},{id:"cs-6122",module:"changshi",prompt:"被称为'浪漫之都'的城市是：",options:["巴黎", "罗马", "维也纳", "马德里"],answer:0,explanation:"法国巴黎塞纳河畔风光旖旎、艺术氛围浓厚，被称为'浪漫之都'。"},{id:"cs-6123",module:"changshi",prompt:"被称为'永恒之城'的城市是：",options:["罗马", "雅典", "开罗", "伊斯坦布尔"],answer:0,explanation:"意大利罗马历史悠久、古迹众多，被称为'永恒之城'。"},{id:"cs-6124",module:"changshi",prompt:"被称为'雾都'的城市是：",options:["伦敦", "巴黎", "柏林", "莫斯科"],answer:0,explanation:"英国伦敦因工业革命时期煤烟污染、多雾而被称为'雾都'，现空气质量已大为改善。"},{id:"cs-6125",module:"changshi",prompt:"被称为'风城'的城市是：",options:["芝加哥", "纽约", "洛杉矶", "旧金山"],answer:0,explanation:"美国芝加哥因密歇根湖畔风力强劲而被称为'风城'。"},{id:"cs-6126",module:"changshi",prompt:"被称为'天使之城'的城市是：",options:["洛杉矶", "纽约", "芝加哥", "迈阿密"],answer:0,explanation:"美国洛杉矶（Los Angeles）西班牙语意为'天使之城'，是美国西海岸最大城市。"},{id:"cs-6127",module:"changshi",prompt:"被称为'大苹果'的城市是：",options:["纽约", "芝加哥", "波士顿", "华盛顿"],answer:0,explanation:"美国纽约被称为'大苹果'（The Big Apple），寓意机遇和梦想之地。"},{id:"cs-6128",module:"changshi",prompt:"被称为'狮城'的城市是：",options:["新加坡", "曼谷", "吉隆坡", "雅加达"],answer:0,explanation:"新加坡（Singapore）梵语意为'狮子城'，是东南亚的城市国家。"},{id:"cs-6129",module:"changshi",prompt:"被称为'东方之珠'的城市是：",options:["香港", "上海", "东京", "首尔"],answer:0,explanation:"香港因繁华璀璨被称为'东方之珠'，是国际金融、贸易和航运中心。"},{id:"cs-6130",module:"changshi",prompt:"被称为'樱花之国'的国家是：",options:["日本", "韩国", "中国", "泰国"],answer:0,explanation:"日本樱花闻名世界，每年春季赏樱是重要习俗，故称'樱花之国'。"},{id:"cs-6131",module:"changshi",prompt:"被称为'枫叶之国'的国家是：",options:["加拿大", "美国", "俄罗斯", "瑞典"],answer:0,explanation:"加拿大枫叶遍布全国，国旗上就有枫叶图案，故称'枫叶之国'。"},{id:"cs-6132",module:"changshi",prompt:"被称为'袋鼠之国'的国家是：",options:["澳大利亚", "新西兰", "南非", "阿根廷"],answer:0,explanation:"澳大利亚是袋鼠的故乡，袋鼠数量远超人口，故称'袋鼠之国'。"},{id:"cs-6133",module:"changshi",prompt:"被称为'绵羊之国'的国家是：",options:["新西兰", "澳大利亚", "英国", "爱尔兰"],answer:0,explanation:"新西兰绵羊数量远超人口，畜牧业发达，故称'绵羊之国'。"},{id:"cs-6134",module:"changshi",prompt:"被称为'风车之国'的国家是：",options:["荷兰", "比利时", "丹麦", "德国"],answer:0,explanation:"荷兰风车历史悠久，用于排水和磨面，故称'风车之国'。"},{id:"cs-6135",module:"changshi",prompt:"被称为'郁金香之国'的国家是：",options:["荷兰", "比利时", "法国", "德国"],answer:0,explanation:"荷兰郁金香种植历史悠久，是世界最大的郁金香生产国，故称'郁金香之国'。"},{id:"cs-6136",module:"changshi",prompt:"被称为'咖啡之国'的国家是：",options:["巴西", "哥伦比亚", "埃塞俄比亚", "越南"],answer:0,explanation:"巴西是世界最大的咖啡生产国，咖啡产量约占全球三分之一，故称'咖啡之国'。"},{id:"cs-6137",module:"changshi",prompt:"被称为'可可之国'的国家是：",options:["科特迪瓦", "加纳", "尼日利亚", "喀麦隆"],answer:0,explanation:"科特迪瓦是世界最大的可可生产国，可可产量占全球40%以上，故称'可可之国'。"},{id:"cs-6138",module:"changshi",prompt:"被称为'香蕉之国'的国家是：",options:["厄瓜多尔", "菲律宾", "哥斯达黎加", "巴拿马"],answer:0,explanation:"厄瓜多尔是世界最大的香蕉出口国，香蕉出口量占全球四分之一以上，故称'香蕉之国'。"},{id:"cs-6139",module:"changshi",prompt:"被称为'橄榄油之国'的国家是：",options:["西班牙", "意大利", "希腊", "土耳其"],answer:0,explanation:"西班牙是世界最大的橄榄油生产国，产量占全球近一半，故称'橄榄油之国'。"},{id:"cs-6140",module:"changshi",prompt:"被称为'葡萄酒之国'的国家是：",options:["法国", "意大利", "西班牙", "葡萄牙"],answer:0,explanation:"法国葡萄酒历史悠久、品质优良，波尔多、勃艮第等产区闻名世界，故称'葡萄酒之国'。"},{id:"cs-6141",module:"changshi",prompt:"被称为'钟表之国'的国家是：",options:["瑞士", "德国", "日本", "法国"],answer:0,explanation:"瑞士钟表工艺精湛，劳力士、欧米茄等品牌闻名世界，故称'钟表之国'。"},{id:"cs-6142",module:"changshi",prompt:"被称为'银行之国'的国家是：",options:["瑞士", "卢森堡", "新加坡", "开曼群岛"],answer:0,explanation:"瑞士银行业发达，保密制度严格，是全球最大的离岸金融中心，故称'银行之国'。"},{id:"cs-6143",module:"changshi",prompt:"被称为'中立之国'的国家是：",options:["瑞士", "瑞典", "奥地利", "芬兰"],answer:0,explanation:"瑞士自1815年起永久中立，未参与两次世界大战，故称'中立之国'。"},{id:"cs-6144",module:"changshi",prompt:"被称为'千湖之国'的国家是：",options:["芬兰", "瑞典", "加拿大", "俄罗斯"],answer:0,explanation:"芬兰境内湖泊众多，有'千湖之国'之称，湖泊约占国土面积的10%。"},{id:"cs-6145",module:"changshi",prompt:"被称为'万岛之国'的国家是：",options:["挪威", "印度尼西亚", "菲律宾", "日本"],answer:0,explanation:"挪威海岸线曲折、岛屿众多，有'万岛之国'之称。"},{id:"cs-6146",module:"changshi",prompt:"被称为'火山之国'的国家是：",options:["印度尼西亚", "日本", "智利", "冰岛"],answer:0,explanation:"印度尼西亚活火山数量居世界首位，故称'火山之国'。"},{id:"cs-6147",module:"changshi",prompt:"被称为'温泉之国'的国家是：",options:["冰岛", "日本", "新西兰", "意大利"],answer:0,explanation:"冰岛地热资源丰富，温泉遍布全国，故称'温泉之国'。"},{id:"cs-6148",module:"changshi",prompt:"被称为'极光之国'的国家是：",options:["挪威", "瑞典", "芬兰", "冰岛"],answer:0,explanation:"挪威北部地处北极圈内，是观赏极光的最佳地点之一，故称'极光之国'。"},{id:"cs-6149",module:"changshi",prompt:"被称为'午夜太阳之国'的国家是：",options:["挪威", "瑞典", "芬兰", "冰岛"],answer:0,explanation:"挪威北部夏季出现极昼现象，太阳终日不落，故称'午夜太阳之国'。"},{id:"cs-6150",module:"changshi",prompt:"被称为'翡翠之岛'的国家是：",options:["爱尔兰", "英国", "冰岛", "新西兰"],answer:0,explanation:"爱尔兰岛上绿草如茵、风景如画，故称'翡翠之岛'。"},{id:"cs-6151",module:"changshi",prompt:"被称为'花园之国'的国家是：",options:["新加坡", "瑞士", "荷兰", "新西兰"],answer:0,explanation:"新加坡城市绿化率高、环境优美，故称'花园之国'。"},{id:"cs-6152",module:"changshi",prompt:"衡量一个国家物价总水平变动的指标是：",options:["CPI", "GDP", "PPI", "PMI"],answer:0,explanation:"CPI（居民消费价格指数）衡量居民消费的物价总水平变动，是观察通货膨胀的重要指标。"},{id:"cs-6153",module:"changshi",prompt:"衡量一个国家工业品出厂价格变动的指标是：",options:["CPI", "PPI", "GDP", "PMI"],answer:1,explanation:"PPI（工业生产者出厂价格指数）衡量工业品出厂价格变动，反映上游价格水平。"},{id:"cs-6154",module:"changshi",prompt:"衡量一个国家制造业景气程度的指标是：",options:["PMI", "CPI", "PPI", "GDP"],answer:0,explanation:"PMI（采购经理指数）衡量制造业和非制造业的景气程度，50%为荣枯线，高于50%表示扩张。"},{id:"cs-6155",module:"changshi",prompt:"衡量一个国家收入分配公平程度的指标是：",options:["基尼系数", "恩格尔系数", "CPI", "GDP"],answer:0,explanation:"基尼系数衡量收入分配公平程度，取值0—1之间，越大表示收入差距越大，0.4为警戒线。"},{id:"cs-6156",module:"changshi",prompt:"衡量一个国家居民生活水平高低的指标是：",options:["恩格尔系数", "基尼系数", "CPI", "GDP"],answer:0,explanation:"恩格尔系数是食品支出占消费总支出的比重，系数越低通常说明生活水平越高。"},{id:"cs-6157",module:"changshi",prompt:"衡量一个国家失业情况的指标是：",options:["失业率", "就业率", "劳动参与率", "人口增长率"],answer:0,explanation:"失业率是失业人口占劳动人口的比重，是衡量经济健康程度的重要指标。"},{id:"cs-6158",module:"changshi",prompt:"中央银行调节货币供应量的工具不包括：",options:["存款准备金率", "公开市场操作", "再贴现率", "财政支出"],answer:3,explanation:"中央银行调节货币供应量的工具包括存款准备金率、公开市场操作、再贴现率等，财政支出是政府财政政策工具。"},{id:"cs-6159",module:"changshi",prompt:"政府调节经济的财政政策工具不包括：",options:["税收", "政府支出", "国债", "利率"],answer:3,explanation:"财政政策工具包括税收、政府支出、国债等，利率是货币政策工具。"},{id:"cs-6160",module:"changshi",prompt:"经济过热时，中央银行应采取的措施是：",options:["提高利率", "降低利率", "增加货币供应量", "减少税收"],answer:0,explanation:"经济过热时应采取紧缩性货币政策，提高利率、减少货币供应量，抑制投资和消费。"},{id:"cs-6161",module:"changshi",prompt:"经济衰退时，政府应采取的措施是：",options:["增加税收", "减少政府支出", "增加政府支出", "提高利率"],answer:2,explanation:"经济衰退时应采取扩张性财政政策，增加政府支出、减少税收，刺激总需求。"},{id:"cs-6162",module:"changshi",prompt:"国际贸易中，一国出口额超过进口额称为：",options:["贸易顺差", "贸易逆差", "贸易平衡", "贸易保护"],answer:0,explanation:"出口额超过进口额称为贸易顺差（出超），反之称为贸易逆差（入超）。"},{id:"cs-6163",module:"changshi",prompt:"国际贸易中，一国对进口商品征收的税称为：",options:["关税", "增值税", "消费税", "所得税"],answer:0,explanation:"关税是对进出口商品征收的税，具有保护本国产业和增加财政收入的作用。"},{id:"cs-6164",module:"changshi",prompt:"世界贸易组织（WTO）的基本原则是：",options:["最惠国待遇和国民待遇", "贸易保护", "配额限制", "补贴出口"],answer:0,explanation:"WTO的基本原则包括最惠国待遇、国民待遇、透明度、自由贸易等，旨在促进全球贸易自由化。"},{id:"cs-6165",module:"changshi",prompt:"汇率上升（本币升值）的影响是：",options:["有利于出口", "有利于进口", "不利于进口", "无影响"],answer:1,explanation:"本币升值使进口商品价格下降，有利于进口；出口商品价格上涨，不利于出口。"},{id:"cs-6166",module:"changshi",prompt:"汇率下降（本币贬值）的影响是：",options:["有利于出口", "有利于进口", "不利于出口", "无影响"],answer:0,explanation:"本币贬值使出口商品价格下降，有利于出口；进口商品价格上涨，不利于进口。"},{id:"cs-6167",module:"changshi",prompt:"外汇储备的主要作用是：",options:["支付国际收支逆差", "增加财政收入", "调节国内物价", "促进消费"],answer:0,explanation:"外汇储备可用于支付国际收支逆差、干预外汇市场、维护汇率稳定，是国家经济安全的重要保障。"},{id:"cs-6168",module:"changshi",prompt:"国际收支平衡表中，经常项目不包括：",options:["货物贸易", "服务贸易", "直接投资", "收益"],answer:2,explanation:"国际收支经常项目包括货物、服务、收益和经常转移；直接投资属于资本和金融项目。"},{id:"cs-6169",module:"changshi",prompt:"国际收支平衡表中，资本和金融项目不包括：",options:["直接投资", "证券投资", "其他投资", "货物贸易"],answer:3,explanation:"资本和金融项目包括直接投资、证券投资、其他投资等；货物贸易属于经常项目。"},{id:"cs-6170",module:"changshi",prompt:"GDP核算的三种方法不包括：",options:["生产法", "收入法", "支出法", "消费法"],answer:3,explanation:"GDP核算方法包括生产法、收入法、支出法三种，不包括消费法。"},{id:"cs-6171",module:"changshi",prompt:"GNP与GDP的区别在于：",options:["是否包括本国公民在国外的收入", "是否包括外国公民在本国的收入", "是否包括政府支出", "是否包括净出口"],answer:0,explanation:"GNP（国民生产总值）按国民计算，包括本国公民在国外的收入；GDP（国内生产总值）按国土计算。"},{id:"cs-6172",module:"changshi",prompt:"名义GDP与实际GDP的区别在于：",options:["是否扣除价格因素", "是否包括服务业", "是否包括政府支出", "是否包括净出口"],answer:0,explanation:"名义GDP按当期价格计算，实际GDP按不变价格计算，扣除了价格因素的影响。"},{id:"cs-6173",module:"changshi",prompt:"衡量一个国家居民收入水平的指标是：",options:["人均GDP", "GDP总量", "GNP", "财政收入"],answer:0,explanation:"人均GDP是GDP除以人口，更能反映居民收入水平和生活水平。"},{id:"cs-6174",module:"changshi",prompt:"衡量一个国家经济发展水平的综合指标是：",options:["GDP", "CPI", "PMI", "基尼系数"],answer:0,explanation:"GDP是衡量一个国家经济发展水平的综合指标，反映经济总量和增长速度。"},{id:"cs-6175",module:"changshi",prompt:"经济增长的三驾马车不包括：",options:["消费", "投资", "出口", "储蓄"],answer:3,explanation:"拉动经济增长的三驾马车是消费、投资和出口（净出口），储蓄不是直接拉动因素。"},{id:"cs-6176",module:"changshi",prompt:"供给侧结构性改革的主要任务是：",options:["去产能、去库存、去杠杆、降成本、补短板", "扩大需求", "增加出口", "提高利率"],answer:0,explanation:"供给侧结构性改革的主要任务是'三去一降一补'，即去产能、去库存、去杠杆、降成本、补短板。"},{id:"cs-6177",module:"changshi",prompt:"'新常态'的主要特征是：",options:["中高速增长、结构优化、动力转换", "高速增长", "低速增长", "负增长"],answer:0,explanation:"'新常态'的主要特征是经济从高速增长转为中高速增长，结构不断优化升级，动力从要素驱动转向创新驱动。"},{id:"cs-6178",module:"changshi",prompt:"'双循环'发展格局是指：",options:["以国内大循环为主体、国内国际双循环相互促进", "以内需为主", "以外需为主", "以内循环为主"],answer:0,explanation:"'双循环'发展格局是以国内大循环为主体、国内国际双循环相互促进，是我国新发展阶段的战略选择。"},{id:"cs-6179",module:"changshi",prompt:"'共同富裕'的内涵是：",options:["全体人民通过辛勤劳动和相互帮助共同过上幸福生活", "平均主义", "同步富裕", "同时富裕"],answer:0,explanation:"'共同富裕'是全体人民通过辛勤劳动和相互帮助共同过上幸福生活，不是平均主义，也不是同步、同时富裕。"},{id:"cs-6180",module:"changshi",prompt:"商务场合中，递名片的正确顺序是：",options:["职位低者先递", "职位高者先递", "年长者先递", "女士先递"],answer:0,explanation:"商务场合递名片应由职位低者先递给职位高者，以示尊重；多人时按职位高低依次递送。"},{id:"cs-6181",module:"changshi",prompt:"商务场合中，握手的正确时长为：",options:["1—3秒", "5—10秒", "10—15秒", "15秒以上"],answer:0,explanation:"商务握手时长以1—3秒为宜，力度适中，注视对方双眼，面带微笑。"},{id:"cs-6182",module:"changshi",prompt:"商务场合中，介绍他人的正确顺序是：",options:["先将职位低者介绍给职位高者", "先将职位高者介绍给职位低者", "先介绍女士", "先介绍年长者"],answer:0,explanation:"商务介绍应先将职位低者介绍给职位高者，以示对尊者的尊重。"},{id:"cs-6183",module:"changshi",prompt:"商务宴请中，主宾应坐在：",options:["主人右侧", "主人左侧", "对面", "任意位置"],answer:0,explanation:"商务宴请中主宾应坐在主人右侧，这是最重要的位置，体现对主宾的尊重。"},{id:"cs-6184",module:"changshi",prompt:"商务宴请中，敬酒的顺序是：",options:["先敬主宾", "先敬长辈", "先敬领导", "随意"],answer:0,explanation:"商务宴请敬酒应先敬主宾，再按职位高低依次敬酒，体现礼节。"},{id:"cs-6185",module:"changshi",prompt:"商务场合中，接听电话的正确做法是：",options:["铃响三声内接听", "铃响后立即接听", "让铃响久一些", "先发短信"],answer:0,explanation:"商务接听电话应在铃响三声内接听，自报家门，语气亲切，通话结束让对方先挂断。"},{id:"cs-6186",module:"changshi",prompt:"商务场合中，乘坐电梯的正确做法是：",options:["先出后进", "先进后出", "随意", "让客人先进"],answer:0,explanation:"乘坐电梯应先出后进，出电梯时让客人先出，进电梯时引导客人后进。"},{id:"cs-6187",module:"changshi",prompt:"商务场合中，乘坐轿车的正确座位是：",options:["后排右座", "后排左座", "副驾驶座", "司机座"],answer:0,explanation:"乘坐由专职司机驾驶的轿车时，后排右座是最尊贵的座位，应让主宾乘坐。"},{id:"cs-6188",module:"changshi",prompt:"商务场合中，接名片的正确做法是：",options:["双手接过并认真看", "单手接过放入口袋", "不看直接收起", "边看边谈"],answer:0,explanation:"接名片应双手接过，认真看一遍并轻声读出对方姓名职务，然后郑重收好。"},{id:"cs-6189",module:"changshi",prompt:"商务场合中，女士化妆的正确做法是：",options:["淡妆为宜", "浓妆艳抹", "不化妆", "在公共场合补妆"],answer:0,explanation:"商务场合女士宜化淡妆，显得自然得体，不要在公共场合补妆。"},{id:"cs-6190",module:"changshi",prompt:"商务场合中，男士着装的正确做法是：",options:["深色西装", "休闲装", "运动装", "花衬衫"],answer:0,explanation:"商务场合男士宜穿深色西装、白衬衫、深色领带、深色皮鞋，显得庄重得体。"},{id:"cs-6191",module:"changshi",prompt:"商务场合中，女士着装的正确做法是：",options:["职业套装", "休闲装", "运动装", "超短裙"],answer:0,explanation:"商务场合女士宜穿职业套装或连衣裙，颜色以素雅为宜，避免过于暴露。"},{id:"cs-6192",module:"changshi",prompt:"商务场合中，交换名片的正确做法是：",options:["双手递接", "单手递接", "抛掷", "折起"],answer:0,explanation:"交换名片应双手递接，名片正面朝向对方，以示尊重。"},{id:"cs-6193",module:"changshi",prompt:"商务场合中，会议座次的安排原则是：",options:["面门为上、以右为尊", "背门为上", "以左为尊", "随意就座"],answer:0,explanation:"商务会议座次安排原则是面门为上、以右为尊，主宾应坐在面向门的位置。"},{id:"cs-6194",module:"changshi",prompt:"商务场合中，送花的正确做法是：",options:["送单数", "送双数", "送菊花", "送白色花"],answer:0,explanation:"商务送花宜送单数（如3、5、7枝），避免送菊花（常用于悼念）和白色花（部分文化中不吉利）。"},{id:"cs-6195",module:"changshi",prompt:"商务场合中，接电话时的正确用语是：",options:["您好，请问找哪位", "喂，找谁", "你是谁", "等一下"],answer:0,explanation:"商务接电话应使用礼貌用语，如'您好，请问找哪位'，语气亲切、态度热情。"},{id:"cs-6196",module:"changshi",prompt:"商务场合中，拜访客户的正确做法是：",options:["提前预约", "突然到访", "迟到", "提前很久到达"],answer:0,explanation:"商务拜访应提前预约，准时到达，不要突然到访或迟到，也不要提前很久到达。"},{id:"cs-6197",module:"changshi",prompt:"商务场合中，会议发言的正确做法是：",options:["简明扼要", "长篇大论", "打断他人", "玩手机"],answer:0,explanation:"商务会议发言应简明扼要、重点突出，不要长篇大论，不要打断他人发言。"},{id:"cs-6198",module:"changshi",prompt:"商务场合中，使用手机的正确做法是：",options:["会议中静音", "会议中接听", "会议中玩游戏", "会议中发短信"],answer:0,explanation:"商务会议中应将手机调至静音或关机，不要接听电话、玩游戏或发短信。"},{id:"cs-6199",module:"changshi",prompt:"商务场合中，用餐时的正确做法是：",options:["不发出声音", "大声喧哗", "用筷子指人", "翻拣菜肴"],answer:0,explanation:"商务用餐应举止文雅，不发出声音，不要用筷子指人或翻拣菜肴。"},{id:"cs-6200",module:"changshi",prompt:"商务场合中，乘坐飞机的正确做法是：",options:["提前到达机场", "迟到", "携带大量现金", "随意更换座位"],answer:0,explanation:"乘坐飞机应提前到达机场（国内航班提前2小时，国际航班提前3小时），遵守安检规定。"},{id:"cs-6201",module:"changshi",prompt:"商务场合中，入住酒店的正确做法是：",options:["保持安静", "大声喧哗", "在走廊吸烟", "随意进入他人房间"],answer:0,explanation:"入住酒店应保持安静，不要大声喧哗，不要在走廊吸烟，不要随意进入他人房间。"},{id:"cs-6202",module:"changshi",prompt:"商务场合中，参加宴会的正确做法是：",options:["准时到达", "迟到", "提前很久到达", "不请自来"],answer:0,explanation:"参加宴会应准时到达，不要迟到，也不要提前很久到达，以免让主人措手不及。"},{id:"cs-6203",module:"changshi",prompt:"商务场合中，接听投诉电话的正确做法是：",options:["耐心倾听", "打断对方", "推卸责任", "挂断电话"],answer:0,explanation:"接听投诉电话应耐心倾听、表示理解，不要打断对方或推卸责任，及时解决问题。"},{id:"cs-6204",module:"changshi",prompt:"商务场合中，处理客户投诉的正确做法是：",options:["及时回应", "拖延时间", "推诿扯皮", "态度冷淡"],answer:0,explanation:"处理客户投诉应及时回应、积极解决，不要拖延时间或推诿扯皮。"},{id:"cs-6205",module:"changshi",prompt:"商务场合中，与外国客户交往的正确做法是：",options:["了解对方文化习俗", "强加自己的习惯", "忽视文化差异", "随意开玩笑"],answer:0,explanation:"与外国客户交往应了解对方文化习俗，尊重差异，避免因文化误解产生冲突。"},{id:"cs-6206",module:"changshi",prompt:"商务场合中，与阿拉伯客户交往的正确做法是：",options:["避免用左手递物", "用左手递物", "随意谈论宗教", "劝酒"],answer:0,explanation:"与阿拉伯客户交往应避免用左手递物（左手被视为不洁），尊重其宗教信仰。"},{id:"cs-6207",module:"changshi",prompt:"商务场合中，与日本客户交往的正确做法是：",options:["鞠躬致意", "拥抱", "拍肩膀", "大声说话"],answer:0,explanation:"与日本客户交往应鞠躬致意，递接名片和物品用双手，避免过于亲昵的肢体接触。"},{id:"cs-6208",module:"changshi",prompt:"商务场合中，与欧美客户交往的正确做法是：",options:["直接坦诚", "含蓄委婉", "过度客套", "回避问题"],answer:0,explanation:"与欧美客户交往应直接坦诚、就事论事，避免过度客套或回避问题。"},{id:"cs-6209",module:"changshi",prompt:"商务场合中，与拉美客户交往的正确做法是：",options:["热情友好", "冷淡疏远", "急于成交", "催促对方"],answer:0,explanation:"与拉美客户交往应热情友好、建立信任，不要急于成交或催促对方。"});
(window.YC_CS_BANK=window.YC_CS_BANK||[]).push({id:"cs-6210",module:"changshi",prompt:"我国近代第一个资产阶级革命团体是：",options:["兴中会", "华兴会", "光复会", "同盟会"],answer:0,explanation:"1894年孙中山在檀香山创立兴中会，是我国近代第一个资产阶级革命团体，提出'振兴中华'口号。"},{id:"cs-6211",module:"changshi",prompt:"我国近代第一个全国性资产阶级革命政党是：",options:["同盟会", "兴中会", "华兴会", "光复会"],answer:0,explanation:"1905年中国同盟会在东京成立，是第一个全国规模的资产阶级革命政党，提出'驱除鞑虏，恢复中华，创立民国，平均地权'纲领。"},{id:"cs-6212",module:"changshi",prompt:"袁世凯复辟帝制的时间是：",options:["1915年", "1916年", "1917年", "1918年"],answer:0,explanation:"1915年12月袁世凯宣布恢复帝制，改国号为'中华帝国'，1916年为洪宪元年，但在护国运动中被迫取消帝制。"},{id:"cs-6213",module:"changshi",prompt:"五四运动的导火索是：",options:["巴黎和会外交失败", "二十一条", "张勋复辟", "府院之争"],answer:0,explanation:"1919年巴黎和会上中国外交失败，山东权益转让给日本，成为五四运动的导火索。"},{id:"cs-6214",module:"changshi",prompt:"中国共产党第一次全国代表大会召开于：",options:["1920年", "1921年", "1922年", "1923年"],answer:1,explanation:"1921年7月中共一大在上海召开（后转移至嘉兴南湖），宣告中国共产党成立。"},{id:"cs-6215",module:"changshi",prompt:"第一次国共合作的政治基础是：",options:["新三民主义", "旧三民主义", "共产主义", "社会主义"],answer:0,explanation:"1924年国民党一大确立联俄、联共、扶助农工三大政策，发展为新三民主义，成为国共合作的政治基础。"},{id:"cs-6216",module:"changshi",prompt:"井冈山革命根据地创建于：",options:["1927年", "1928年", "1929年", "1930年"],answer:0,explanation:"1927年10月毛泽东率秋收起义部队到达井冈山，创建第一个农村革命根据地，开辟了农村包围城市的道路。"},{id:"cs-6217",module:"changshi",prompt:"红军长征开始的标志是：",options:["中央红军离开瑞金", "遵义会议召开", "会宁会师", "四渡赤水"],answer:0,explanation:"1934年10月中央红军从江西瑞金出发，开始长征；1936年10月三大主力在甘肃会宁会师，长征胜利结束。"},{id:"cs-6218",module:"changshi",prompt:"抗战以来中国军队取得的第一次大捷是：",options:["平型关大捷", "台儿庄战役", "百团大战", "淞沪会战"],answer:0,explanation:"1937年9月八路军115师在平型关伏击日军，取得抗战以来中国军队的第一次大捷。"},{id:"cs-6219",module:"changshi",prompt:"抗战时期正面战场取得的最大胜利是：",options:["台儿庄战役", "平型关大捷", "武汉会战", "长沙会战"],answer:0,explanation:"1938年李宗仁指挥的台儿庄战役歼敌一万余人，是抗战以来正面战场取得的最大胜利。"},{id:"cs-6220",module:"changshi",prompt:"八路军发动的最大规模战役是：",options:["百团大战", "平型关大捷", "黄土岭战斗", "神头岭战斗"],answer:0,explanation:"1940年彭德怀指挥八路军发动百团大战，参战兵力达105个团，沉重打击了日军的'囚笼政策'。"},{id:"cs-6221",module:"changshi",prompt:"中共七大确立的指导思想是：",options:["毛泽东思想", "邓小平理论", "三个代表", "科学发展观"],answer:0,explanation:"1945年中共七大在延安召开，确立毛泽东思想为党的指导思想，为抗战胜利和新民主主义革命胜利奠定基础。"},{id:"cs-6222",module:"changshi",prompt:"解放战争战略决战的三大战役不包括：",options:["辽沈战役", "淮海战役", "平津战役", "渡江战役"],answer:3,explanation:"三大战役指辽沈、淮海、平津战役；渡江战役是三大战役后解放南京的战役。"},{id:"cs-6223",module:"changshi",prompt:"中华人民共和国成立于：",options:["1949年9月", "1949年10月", "1950年1月", "1948年10月"],answer:1,explanation:"1949年10月1日中华人民共和国中央人民政府在北京宣告成立，毛泽东当选中央人民政府主席。"},{id:"cs-6224",module:"changshi",prompt:"我国社会主义制度基本建立的标志是：",options:["三大改造完成", "土地改革完成", "一五计划完成", "抗美援朝胜利"],answer:0,explanation:"1956年三大改造（农业、手工业、资本主义工商业的社会主义改造）完成，标志着社会主义制度基本建立。"},{id:"cs-6225",module:"changshi",prompt:"我国进入改革开放新时期的标志是：",options:["十一届三中全会", "十二大", "十三大", "十四大"],answer:0,explanation:"1978年12月十一届三中全会作出把工作重心转移到经济建设上来、实行改革开放的决策，我国进入改革开放新时期。"},{id:"cs-6226",module:"changshi",prompt:"我国建立经济特区的决策是在：",options:["1979年", "1980年", "1984年", "1992年"],answer:1,explanation:"1980年我国设立深圳、珠海、汕头、厦门四个经济特区，1988年增设海南，成为对外开放的窗口。"},{id:"cs-6227",module:"changshi",prompt:"我国加入世界贸易组织的时间是：",options:["1999年", "2000年", "2001年", "2002年"],answer:2,explanation:"2001年12月11日我国正式加入世界贸易组织（WTO），成为第143个成员。"},{id:"cs-6228",module:"changshi",prompt:"我国首次载人航天飞行成功的时间是：",options:["1999年", "2003年", "2005年", "2008年"],answer:1,explanation:"2003年10月神舟五号载人飞船发射成功，杨利伟成为我国第一位进入太空的航天员。"},{id:"cs-6229",module:"changshi",prompt:"我国举办奥运会的年份是：",options:["2004年", "2008年", "2012年", "2016年"],answer:1,explanation:"2008年北京举办第29届夏季奥运会，我国体育代表团获得51枚金牌，居金牌榜首位。"},{id:"cs-6230",module:"changshi",prompt:"我国提出'一带一路'倡议的时间是：",options:["2012年", "2013年", "2014年", "2015年"],answer:1,explanation:"2013年习近平提出共建'丝绸之路经济带'和'21世纪海上丝绸之路'倡议，简称'一带一路'。"},{id:"cs-6231",module:"changshi",prompt:"被称为'乐圣'的音乐家是：",options:["贝多芬", "莫扎特", "巴赫", "海顿"],answer:0,explanation:"德国作曲家贝多芬被尊为'乐圣'，代表作有《命运交响曲》《欢乐颂》等。"},{id:"cs-6232",module:"changshi",prompt:"被称为'音乐神童'的音乐家是：",options:["莫扎特", "贝多芬", "巴赫", "海顿"],answer:0,explanation:"奥地利作曲家莫扎特自幼展现音乐天赋，6岁开始巡回演出，被称为'音乐神童'。"},{id:"cs-6233",module:"changshi",prompt:"被称为'西方音乐之父'的音乐家是：",options:["巴赫", "亨德尔", "海顿", "莫扎特"],answer:0,explanation:"德国作曲家巴赫是巴洛克音乐的集大成者，被尊为'西方音乐之父'。"},{id:"cs-6234",module:"changshi",prompt:"被称为'交响乐之父'的音乐家是：",options:["海顿", "莫扎特", "贝多芬", "巴赫"],answer:0,explanation:"奥地利作曲家海顿确立了交响曲的四乐章结构，被称为'交响乐之父'。"},{id:"cs-6235",module:"changshi",prompt:"被称为'歌曲之王'的音乐家是：",options:["舒伯特", "舒曼", "勃拉姆斯", "李斯特"],answer:0,explanation:"奥地利作曲家舒伯特一生创作600多首艺术歌曲，被称为'歌曲之王'。"},{id:"cs-6236",module:"changshi",prompt:"被称为'钢琴诗人'的音乐家是：",options:["肖邦", "李斯特", "舒曼", "门德尔松"],answer:0,explanation:"波兰作曲家肖邦一生创作大量钢琴作品，被称为'钢琴诗人'。"},{id:"cs-6237",module:"changshi",prompt:"被称为'钢琴之王'的音乐家是：",options:["李斯特", "肖邦", "舒曼", "门德尔松"],answer:0,explanation:"匈牙利作曲家李斯特钢琴技巧精湛，被称为'钢琴之王'。"},{id:"cs-6238",module:"changshi",prompt:"被称为'圆舞曲之王'的音乐家是：",options:["小约翰·施特劳斯", "老约翰·施特劳斯", "肖邦", "李斯特"],answer:0,explanation:"奥地利作曲家小约翰·施特劳斯创作《蓝色多瑙河》等圆舞曲，被称为'圆舞曲之王'。"},{id:"cs-6239",module:"changshi",prompt:"被称为'柴可夫斯基'的音乐家来自：",options:["俄罗斯", "德国", "法国", "意大利"],answer:0,explanation:"俄国作曲家柴可夫斯基代表作有《天鹅湖》《胡桃夹子》《第六交响曲》等。"},{id:"cs-6240",module:"changshi",prompt:"歌剧《卡门》的作者是：",options:["比才", "威尔第", "普契尼", "罗西尼"],answer:0,explanation:"法国作曲家比才的歌剧《卡门》是世界上演率最高的歌剧之一。"},{id:"cs-6241",module:"changshi",prompt:"歌剧《茶花女》的作者是：",options:["威尔第", "比才", "普契尼", "罗西尼"],answer:0,explanation:"意大利作曲家威尔第的歌剧《茶花女》改编自小仲马同名小说。"},{id:"cs-6242",module:"changshi",prompt:"歌剧《图兰朵》中运用了中国旋律：",options:["《茉莉花》", "《康定情歌》", "《二泉映月》", "《梁祝》"],answer:0,explanation:"意大利作曲家普契尼的歌剧《图兰朵》中运用了中国民歌《茉莉花》的旋律。"},{id:"cs-6243",module:"changshi",prompt:"我国国粹京剧形成于：",options:["清朝", "明朝", "元朝", "民国"],answer:0,explanation:"京剧形成于清朝道光年间，由徽剧、汉剧融合演变而成，2010年被列入人类非物质文化遗产。"},{id:"cs-6244",module:"changshi",prompt:"京剧'四大名旦'不包括：",options:["梅兰芳", "程砚秋", "荀慧生", "周信芳"],answer:3,explanation:"京剧'四大名旦'指梅兰芳、程砚秋、荀慧生、尚小云；周信芳是'麒麟童'，为生行名家。"},{id:"cs-6245",module:"changshi",prompt:"我国第一部电影《定军山》拍摄于：",options:["1905年", "1913年", "1921年", "1931年"],answer:0,explanation:"1905年北京丰泰照相馆拍摄京剧《定军山》片段，是我国第一部电影。"},{id:"cs-6246",module:"changshi",prompt:"我国第一部有声电影是：",options:["《歌女红牡丹》", "《定军山》", "《难夫难妻》", "《孤儿救祖记》"],answer:0,explanation:"1931年《歌女红牡丹》是我国第一部有声电影。"},{id:"cs-6247",module:"changshi",prompt:"我国第一部彩色电影是：",options:["《生死恨》", "《歌女红牡丹》", "《定军山》", "《难夫难妻》"],answer:0,explanation:"1948年《生死恨》是我国第一部彩色电影，由梅兰芳主演。"},{id:"cs-6248",module:"changshi",prompt:"我国第一部在国际上获奖的电影是：",options:["《渔光曲》", "《定军山》", "《歌女红牡丹》", "《生死恨》"],answer:0,explanation:"1935年《渔光曲》在莫斯科国际电影节获奖，是我国第一部在国际上获奖的电影。"},{id:"cs-6249",module:"changshi",prompt:"我国第一座电影院建于：",options:["上海", "北京", "天津", "广州"],answer:0,explanation:"1908年上海建成虹口大戏院，是我国第一座电影院。"},{id:"cs-6250",module:"changshi",prompt:"我国第一部电视剧是：",options:["《一口菜饼子》", "《敌营十八年》", "《渴望》", "《西游记》"],answer:0,explanation:"1958年《一口菜饼子》是我国第一部电视剧。"},{id:"cs-6251",module:"changshi",prompt:"我国第一部大型室内电视连续剧是：",options:["《渴望》", "《敌营十八年》", "《一口菜饼子》", "《西游记》"],answer:0,explanation:"1990年《渴望》是我国第一部大型室内电视连续剧，引起轰动。"},{id:"cs-6252",module:"changshi",prompt:"我国第一部动画长片是：",options:["《铁扇公主》", "《大闹画室》", "《小蝌蚪找妈妈》", "《大闹天宫》"],answer:0,explanation:"1941年《铁扇公主》是我国第一部动画长片。"},{id:"cs-6253",module:"changshi",prompt:"我国第一部水墨动画片是：",options:["《小蝌蚪找妈妈》", "《铁扇公主》", "《大闹天宫》", "《哪吒闹海》"],answer:0,explanation:"1961年《小蝌蚪找妈妈》是我国第一部水墨动画片，取材于齐白石的画作。"},{id:"cs-6254",module:"changshi",prompt:"我国第一部大型彩色宽银幕动画长片是：",options:["《大闹天宫》", "《哪吒闹海》", "《小蝌蚪找妈妈》", "《铁扇公主》"],answer:0,explanation:"1964年《大闹天宫》是我国第一部大型彩色宽银幕动画长片。"},{id:"cs-6255",module:"changshi",prompt:"我国第一部科幻电影是：",options:["《珊瑚岛上的死光》", "《流浪地球》", "《疯狂的外星人》", "《长江七号》"],answer:0,explanation:"1980年《珊瑚岛上的死光》是我国第一部科幻电影。"},{id:"cs-6256",module:"changshi",prompt:"我国第一部3D电影是：",options:["《唐山大地震》", "《阿凡达》", "《龙门飞甲》", "《画皮2》"],answer:2,explanation:"2011年《龙门飞甲》是我国第一部3D武侠电影。"},{id:"cs-6257",module:"changshi",prompt:"第一届现代奥运会举办于：",options:["1896年雅典", "1900年巴黎", "1904年圣路易斯", "1908年伦敦"],answer:0,explanation:"1896年第一届现代奥运会在希腊雅典举行，此后每四年举办一届。"},{id:"cs-6258",module:"changshi",prompt:"第一届冬季奥运会举办于：",options:["1924年夏慕尼", "1924年巴黎", "1920年安特卫普", "1928年圣莫里茨"],answer:0,explanation:"1924年第一届冬季奥运会在法国夏慕尼举行。"},{id:"cs-6259",module:"changshi",prompt:"世界杯足球赛首次举办于：",options:["1930年乌拉圭", "1934年意大利", "1938年法国", "1950年巴西"],answer:0,explanation:"1930年第一届世界杯足球赛在乌拉圭举行，乌拉圭队夺冠。"},{id:"cs-6260",module:"changshi",prompt:"我国第一枚冬奥会金牌的获得者是：",options:["杨扬", "王濛", "武大靖", "周洋"],answer:0,explanation:"2002年盐湖城冬奥会上，杨扬获得短道速滑500米冠军，实现了我国冬奥会金牌零的突破。"},{id:"cs-6261",module:"changshi",prompt:"我国第一位获得奥运田径金牌的运动员是：",options:["刘翔", "许海峰", "李宁", "王军霞"],answer:0,explanation:"2004年雅典奥运会上，刘翔获得110米栏冠军，是我国第一位获得奥运田径金牌的男运动员。"},{id:"cs-6262",module:"changshi",prompt:"我国男足唯一一次进入世界杯是在：",options:["1998年", "2002年", "2006年", "2010年"],answer:1,explanation:"2002年韩日世界杯，我国男足首次进入世界杯决赛圈。"},{id:"cs-6263",module:"changshi",prompt:"我国第一次举办奥运会的城市是：",options:["北京", "上海", "广州", "深圳"],answer:0,explanation:"2008年北京举办第29届夏季奥运会，是我国第一次举办奥运会。"},{id:"cs-6264",module:"changshi",prompt:"我国第一次举办冬奥会的城市是：",options:["北京", "哈尔滨", "长春", "沈阳"],answer:0,explanation:"2022年北京举办第24届冬季奥运会，成为首个'双奥之城'。"},{id:"cs-6265",module:"changshi",prompt:"我国第一枚亚运会金牌的获得者是：",options:["苏之勃", "李宁", "许海峰", "郎平"],answer:0,explanation:"1974年德黑兰亚运会上，苏之勃获得男子手枪慢射冠军，是我国第一枚亚运会金牌。"},{id:"cs-6266",module:"changshi",prompt:"我国第一次举办亚运会的城市是：",options:["北京", "广州", "杭州", "上海"],answer:0,explanation:"1990年北京举办第11届亚运会，是我国第一次举办亚运会。"},{id:"cs-6267",module:"changshi",prompt:"我国第一次举办世博会的城市是：",options:["上海", "北京", "广州", "深圳"],answer:0,explanation:"2010年上海举办第41届世界博览会，是我国第一次举办世博会。"},{id:"cs-6268",module:"changshi",prompt:"我国第一次举办APEC会议的城市是：",options:["上海", "北京", "杭州", "青岛"],answer:0,explanation:"2001年上海举办APEC会议，是我国第一次举办APEC会议。"},{id:"cs-6269",module:"changshi",prompt:"我国第一次举办G20峰会的城市是：",options:["杭州", "上海", "北京", "青岛"],answer:0,explanation:"2016年杭州举办G20峰会，是我国第一次举办G20峰会。"},{id:"cs-6270",module:"changshi",prompt:"我国第一次举办金砖国家峰会的城市是：",options:["三亚", "厦门", "福州", "成都"],answer:0,explanation:"2011年三亚举办金砖国家峰会，是我国第一次举办金砖国家峰会。"},{id:"cs-6271",module:"changshi",prompt:"我国第一次举办上合组织峰会的城市是：",options:["上海", "北京", "青岛", "郑州"],answer:0,explanation:"2001年上海举办上合组织峰会，宣告上海合作组织成立。"},{id:"cs-6272",module:"changshi",prompt:"我国第一次举办中非合作论坛峰会的城市是：",options:["北京", "上海", "广州", "成都"],answer:0,explanation:"2000年北京举办中非合作论坛峰会，是我国第一次举办中非合作论坛峰会。"},{id:"cs-6273",module:"changshi",prompt:"我国第一次举办'一带一路'国际合作高峰论坛的城市是：",options:["北京", "上海", "西安", "乌鲁木齐"],answer:0,explanation:"2017年北京举办'一带一路'国际合作高峰论坛，是我国第一次举办该论坛。"},{id:"cs-6274",module:"changshi",prompt:"我国第一次举办进博会的城市是：",options:["上海", "北京", "广州", "深圳"],answer:0,explanation:"2018年上海举办首届中国国际进口博览会，是世界上首个以进口为主题的国家级展会。"},{id:"cs-6275",module:"changshi",prompt:"我国第一次举办冬奥会的年份是：",options:["2018年", "2020年", "2022年", "2024年"],answer:2,explanation:"2022年北京举办第24届冬季奥运会，是我国第一次举办冬奥会。"},{id:"cs-6276",module:"changshi",prompt:"我国第一次举办亚运会的年份是：",options:["1988年", "1990年", "1992年", "1994年"],answer:1,explanation:"1990年北京举办第11届亚运会，是我国第一次举办亚运会。"},{id:"cs-6277",module:"changshi",prompt:"我国第一次举办世博会的年份是：",options:["2008年", "2010年", "2012年", "2014年"],answer:1,explanation:"2010年上海举办第41届世界博览会，是我国第一次举办世博会。"},{id:"cs-6278",module:"changshi",prompt:"我国第一次举办APEC会议的年份是：",options:["1999年", "2001年", "2003年", "2005年"],answer:1,explanation:"2001年上海举办APEC会议，是我国第一次举办APEC会议。"},{id:"cs-6279",module:"changshi",prompt:"我国第一次举办G20峰会的年份是：",options:["2014年", "2016年", "2018年", "2020年"],answer:1,explanation:"2016年杭州举办G20峰会，是我国第一次举办G20峰会。"},{id:"cs-6280",module:"changshi",prompt:"我国第一次举办金砖国家峰会的年份是：",options:["2009年", "2011年", "2013年", "2015年"],answer:1,explanation:"2011年三亚举办金砖国家峰会，是我国第一次举办金砖国家峰会。"},{id:"cs-6281",module:"changshi",prompt:"我国第一次举办上合组织峰会的年份是：",options:["1999年", "2001年", "2003年", "2005年"],answer:1,explanation:"2001年上海举办上合组织峰会，宣告上海合作组织成立。"},{id:"cs-6282",module:"changshi",prompt:"家庭中预防食物中毒，剩菜剩饭的正确处理方式是：",options:["室温存放隔夜再吃", "趁热密封后冷藏并尽快食用", "反复加热多次食用", "与生食混放保存"],answer:1,explanation:"熟食应及时密封冷藏（5℃以下）并尽快食用，室温久放易滋生细菌导致食物中毒。"},{id:"cs-6283",module:"changshi",prompt:"使用燃气热水器洗澡时，为防止一氧化碳中毒，最重要的是：",options:["调高水温", "保持室内通风", "关闭门窗保暖", "先冲头后冲身"],answer:1,explanation:"燃气燃烧不充分会产生一氧化碳，保持通风是预防一氧化碳中毒的关键。"},{id:"cs-6284",module:"changshi",prompt:"家用电器起火时，第一步应当：",options:["立即泼水灭火", "先切断电源再灭火", "用湿布覆盖", "打开门窗散烟"],answer:1,explanation:"电器起火应先断电，带电泼水可能引发触电和短路扩大火势。"},{id:"cs-6285",module:"changshi",prompt:"被猫狗抓咬伤后，正确的第一步处理是：",options:["涂红药水消毒", "立即用肥皂水和流动清水交替冲洗伤口", "用嘴吸出污血", "包扎伤口不透气"],answer:1,explanation:"应立即用肥皂水和流动清水交替冲洗伤口至少15分钟，并尽快就医接种狂犬疫苗。"},{id:"cs-6286",module:"changshi",prompt:"乘坐电梯突然下坠时，比较合理的自我保护动作是：",options:["不停跳跃", "迅速把每一层按键都按下并背靠墙壁屈膝", "扒门爬出", "平躺在轿厢地面"],answer:1,explanation:"按下每层按键增加停靠机会，背部贴墙、屈膝踮脚可减轻落地冲击，切勿扒门。"},{id:"cs-6287",module:"changshi",prompt:"雷雨天气在户外时，正确的做法是：",options:["到大树下避雨", "远离孤立大树、电线杆和铁栏", "在空旷处打伞奔跑", "触摸金属栏杆"],answer:1,explanation:"雷雨时应远离高大孤立物体和金属物，避免成为雷击目标，可进入低矮建筑物躲避。"},{id:"cs-6288",module:"changshi",prompt:"发现家中煤气泄漏，正确的做法是：",options:["开灯查看泄漏点", "关闭阀门、开窗通风，勿动电器开关", "用打火机试漏", "打电话报修"],answer:1,explanation:"煤气泄漏时任何电火花都可能引发爆炸，应先关阀开窗，到室外安全处再打电话。"},{id:"cs-6289",module:"changshi",prompt:"烫伤后正确的紧急处理是：",options:["涂牙膏或酱油", "用流动冷水冲洗降温", "挑破水泡", "用冰块直接敷创面"],answer:1,explanation:"烫伤应立即用流动冷水冲15分钟以上降温，不要涂牙膏酱油，也不要挑破水泡。"},{id:"cs-6290",module:"changshi",prompt:"地震发生时在室内，比较安全的做法是：",options:["立即跳窗逃生", "就近躲到坚固桌下或承重墙角，护住头颈", "乘电梯下楼", "站在窗边观察"],answer:1,explanation:"室内避震应就近躲避在坚固家具旁或墙角，护住头部，震后有序撤离，切勿跳窗或乘电梯。"},{id:"cs-6291",module:"changshi",prompt:"流鼻血时正确的止血方法是：",options:["仰头止血", "低头前倾，捏住鼻翼压迫止血", "用纸团塞鼻孔深处", "抬对侧手臂"],answer:1,explanation:"应低头前倾捏住鼻翼持续压迫5-10分钟，仰头会使血液流入咽喉引起呛咳。"},{id:"cs-6292",module:"changshi",prompt:"食品包装上的生产日期和保质期属于：",options:["广告用语", "强制性标注的食品安全信息", "企业自选信息", "商标信息"],answer:1,explanation:"预包装食品必须依法标注生产日期、保质期等强制信息，是判断食品是否安全可食的依据。"},{id:"cs-6293",module:"changshi",prompt:"长期用嘴呼吸代替鼻呼吸，主要的不利影响是：",options:["摄入氧气更多", "呼吸道失去过滤加温加湿作用，易引发感染", "肺活量增大", "声音变好听"],answer:1,explanation:"鼻腔可过滤、加温、加湿空气，长期口呼吸使呼吸道直接暴露，易引发咽炎和呼吸道感染。"},{id:"cs-6294",module:"changshi",prompt:"家庭药箱存放药品的正确做法是：",options:["所有药混装一盒", "分类存放、保留说明书、定期检查有效期", "放冰箱冷冻室", "拆掉原包装方便取用"],answer:1,explanation:"药品应按原包装分类存放，保留说明书，避光防潮，并定期清理过期药品。"},{id:"cs-6295",module:"changshi",prompt:"手机充电时正确的做法是：",options:["边玩大型游戏边充", "使用原装或合格充电器，避免高温环境充电", "用湿手插拔充电器", "充满后整夜不拔"],answer:1,explanation:"应使用合格充电器，避免高温和长时间过充，湿手插拔有触电风险。"},{id:"cs-6296",module:"changshi",prompt:"发生火灾逃生时，穿过烟雾区正确的方法是：",options:["直立快跑", "用湿毛巾捂住口鼻，弯腰低姿前进", "深呼吸快速通过", "大声呼喊不停留"],answer:1,explanation:"烟雾中一氧化碳和毒气聚集在上层，湿毛巾捂口鼻、低姿前进可减少吸入有毒烟气。"},{id:"cs-6297",module:"changshi",prompt:"关于饮用水烧开后饮用，正确的说法是：",options:["水烧开后可反复多次煮沸", "烧开可杀灭致病微生物，但不宜反复煮沸", "生水更营养", "烧开的水可无限期存放"],answer:1,explanation:"烧开能杀灭水中致病微生物；反复煮沸会使水中某些矿物质浓缩，存放过久易滋生细菌。"},{id:"cs-6298",module:"changshi",prompt:"久坐办公室的人预防颈椎病，最有效的措施是：",options:["买高档颈椎枕", "定时起身活动，调整坐姿和屏幕高度", "长期戴颈托", "多做低头拉伸"],answer:1,explanation:"颈椎病重在预防：定时活动、保持正确坐姿、屏幕与视线平齐比被动器械更有效。"},{id:"cs-6299",module:"changshi",prompt:"乘坐长途汽车或飞机时，为预防下肢深静脉血栓，应当：",options:["全程不动休息", "定时起身活动或做踝泵运动，多喝水", "穿紧身裤", "大量饮酒助眠"],answer:1,explanation:"长时间静坐易形成下肢血栓，定时活动、做踝泵运动和补水可促进血液循环。"},{id:"cs-6300",module:"changshi",prompt:"家庭中过期药品的正确处理方式是：",options:["冲入下水道", "投入过期药品回收点或按有害垃圾分类处理", "当普通垃圾扔掉", "碾碎后混入土壤"],answer:1,explanation:"过期药品属于有害垃圾，应投入药品回收点，随意丢弃或冲入下水道会污染环境。"},{id:"cs-6301",module:"changshi",prompt:"关于人体必需的营养素，下列属于微量元素的是：",options:["钙", "铁", "磷", "钠"],answer:1,explanation:"铁是人体必需的微量元素，钙、磷、钠属于常量元素。"},{id:"cs-6302",module:"changshi",prompt:"运动后大量出汗，补充水分最合理的方式是：",options:["一次性猛灌大量冰水", "少量多次补充温水，可适当补充电解质", "只喝碳酸饮料", "不渴就不喝"],answer:1,explanation:"大量出汗后应少量多次补水，出汗量大时可补充电解质，猛灌冰水易刺激肠胃。"},{id:"cs-6303",module:"changshi",prompt:"关于抗生素的使用，正确的说法是：",options:["感冒都应服用抗生素", "抗生素对病毒无效，应遵医嘱使用", "抗生素越贵越好", "症状好转即可自行停药"],answer:1,explanation:"普通感冒多由病毒引起，抗生素只对细菌有效；滥用抗生素会导致耐药性，须遵医嘱足量足疗程使用。"},{id:"cs-6304",module:"changshi",prompt:"我国居民膳食指南建议，成年人每天摄入食盐不超过：",options:["3克", "5克", "10克", "15克"],answer:1,explanation:"《中国居民膳食指南（2022）》建议成年人每日食盐摄入量不超过5克。"},{id:"cs-6305",module:"changshi",prompt:"体检报告中的空腹血糖检测，要求至少禁食：",options:["4小时", "8小时", "12小时", "24小时"],answer:1,explanation:"空腹血糖要求禁食8-12小时，一般从前一晚晚餐后不再进食，次日晨采血。"},{id:"cs-6306",module:"changshi",prompt:"关于近视的预防，正确的说法是：",options:["近视后戴眼镜会加深度数", "增加户外活动时间有助于预防近视", "眼保健操可治愈近视", "看绿色就能治疗近视"],answer:1,explanation:"每天2小时以上户外活动可显著降低近视发生率；近视后科学配镜不会加深度数。"},{id:"cs-6307",module:"changshi",prompt:"垃圾分类中，废旧电池（如纽扣电池）应投入：",options:["厨余垃圾", "有害垃圾", "可回收物", "其他垃圾"],answer:1,explanation:"废旧电池含汞、镉等重金属，属于有害垃圾，随意丢弃会污染土壤和水源。"},{id:"cs-6308",module:"changshi",prompt:"家庭安全用电，下列做法正确的是：",options:["用湿手拔插头", "大功率电器不共用一个插线板", "电线老化后继续使用", "电器带电擦拭"],answer:1,explanation:"大功率电器共用插线板易过载引发火灾；湿手操作、老化电线继续使用都有安全隐患。"},{id:"cs-6309",module:"changshi",prompt:"乘坐私家车时，儿童正确的乘车方式是：",options:["抱在成人怀中", "使用与年龄体重相符的儿童安全座椅", "系成人安全带即可", "坐在副驾驶"],answer:1,explanation:"儿童应使用符合标准的儿童安全座椅，成人怀抱在碰撞时无法提供有效保护，副驾驶更危险。"},{id:"cs-6310",module:"changshi",prompt:"关于熬夜对健康的影响，正确的说法是：",options:["周末补觉可完全抵消熬夜伤害", "长期熬夜会扰乱生物钟，增加多种疾病风险", "熬夜只影响皮肤", "年轻人熬夜无碍健康"],answer:1,explanation:"长期熬夜扰乱昼夜节律，与心血管疾病、代谢紊乱、免疫力下降相关，补觉无法完全弥补。"});
(window.YC_CS_BANK=window.YC_CS_BANK||[]).push({id:"cs-6311",module:"changshi",prompt:"长江与黄河都发源于的省份是：",options:["西藏", "青海", "四川", "甘肃"],answer:1,explanation:"长江发源于唐古拉山，黄河发源于巴颜喀拉山，均位于青海省。"},{id:"cs-6312",module:"changshi",prompt:"我国地势第二级阶梯与第三级阶梯分界线上的山脉是：",options:["昆仑山", "大兴安岭", "祁连山", "横断山"],answer:1,explanation:"二三阶梯分界线为大兴安岭—太行山—巫山—雪峰山；昆仑山和祁连山位于一二阶梯分界线上。"},{id:"cs-6313",module:"changshi",prompt:"被称为'塞外江南'的地区是：",options:["河西走廊", "宁夏平原与河套平原", "吐鲁番盆地", "呼伦贝尔草原"],answer:1,explanation:"宁夏平原和河套平原引黄河水灌溉，农业发达，被誉为'塞外江南'。"},{id:"cs-6314",module:"changshi",prompt:"我国少数民族最多的省份是：",options:["云南", "贵州", "广西", "四川"],answer:0,explanation:"云南省有25个世居少数民族，是我国少数民族种类最多的省份。"},{id:"cs-6315",module:"changshi",prompt:"'三山五岳'中的'五岳'不包括：",options:["泰山", "华山", "黄山", "衡山"],answer:2,explanation:"五岳为东岳泰山、西岳华山、南岳衡山、北岳恒山、中岳嵩山；黄山不属于五岳。"},{id:"cs-6316",module:"changshi",prompt:"京杭大运河沟通的五大水系不包括：",options:["海河", "黄河", "淮河", "赣江"],answer:3,explanation:"京杭大运河沟通海河、黄河、淮河、长江、钱塘江五大水系，不经过赣江。"},{id:"cs-6317",module:"changshi",prompt:"被称为'世界屋脊'的高原是：",options:["青藏高原", "内蒙古高原", "黄土高原", "云贵高原"],answer:0,explanation:"青藏高原平均海拔4000米以上，是世界上海拔最高的高原，被称为'世界屋脊'。"},{id:"cs-6318",module:"changshi",prompt:"我国最大的丘陵集中分布区是：",options:["东南丘陵", "山东丘陵", "辽东丘陵", "黄土丘陵"],answer:0,explanation:"东南丘陵位于长江以南、云贵高原以东，是我国面积最大的丘陵分布区。"},{id:"cs-6319",module:"changshi",prompt:"我国冬季气温南北温差大，主要原因是：",options:["纬度位置与冬季风影响", "海陆位置", "地形起伏", "洋流影响"],answer:0,explanation:"冬季太阳直射南半球，北方正午太阳高度低且白昼短，加之冬季风加剧北方寒冷，故南北温差大。"},{id:"cs-6320",module:"changshi",prompt:"我国年降水量分布的总趋势是：",options:["从南向北递增", "从东南沿海向西北内陆递减", "从东向西递增", "全国均匀分布"],answer:1,explanation:"受夏季风影响，我国降水从东南沿海向西北内陆递减，西北地区降水稀少。"},{id:"cs-6321",module:"changshi",prompt:"塔里木河的主要补给水源是：",options:["大气降水", "冰雪融水", "地下水", "湖泊水"],answer:1,explanation:"塔里木河地处干旱区，主要靠昆仑山、天山等高山冰雪融水补给，夏季为汛期。"},{id:"cs-6322",module:"changshi",prompt:"我国四大牧区不包括：",options:["内蒙古牧区", "新疆牧区", "青海牧区", "黑龙江牧区"],answer:3,explanation:"我国四大牧区为内蒙古、新疆、青海、西藏牧区，黑龙江不属于四大牧区。"},{id:"cs-6323",module:"changshi",prompt:"我国最大的煤炭储量和产区所在的省份是：",options:["陕西", "山西", "内蒙古", "新疆"],answer:1,explanation:"山西省煤炭资源丰富，素有'煤海'之称，长期是我国最大煤炭产区。"},{id:"cs-6324",module:"changshi",prompt:"长江干流流经的直辖市是：",options:["重庆", "天津", "上海", "北京"],answer:0,explanation:"长江干流流经重庆和上海两个直辖市，天津不临长江。"},{id:"cs-6325",module:"changshi",prompt:"我国最大的淡水鱼养殖基地所在的湖泊水系是：",options:["洞庭湖水系", "长江中下游湖泊水系", "珠江水系", "黑龙江水系"],answer:1,explanation:"长江中下游湖泊众多，是我国淡水渔业最发达的地区，被称为'鱼米之乡'。"},{id:"cs-6326",module:"changshi",prompt:"'喀斯特地貌'在我国最典型的分布区是：",options:["云贵高原", "内蒙古高原", "华北平原", "东北平原"],answer:0,explanation:"云贵高原石灰岩广布，喀斯特地貌发育典型，多溶洞、天坑和地下河。"},{id:"cs-6327",module:"changshi",prompt:"海南岛与雷州半岛之间的海峡是：",options:["渤海海峡", "琼州海峡", "台湾海峡", "巴士海峡"],answer:1,explanation:"琼州海峡位于海南岛与雷州半岛之间，是我国的内水航道。"},{id:"cs-6328",module:"changshi",prompt:"我国领土最东端所在的省份是：",options:["吉林", "黑龙江", "内蒙古", "辽宁"],answer:1,explanation:"我国领土最东端在黑龙江与乌苏里江主航道中心线相交处，位于黑龙江省。"},{id:"cs-6329",module:"changshi",prompt:"'看不见的手'这一经济学概念出自：",options:["《国富论》", "《就业、利息和货币通论》", "《资本论》", "《经济学原理》"],answer:0,explanation:"亚当·斯密在《国富论》中提出'看不见的手'，指市场机制对经济的自发调节作用。"},{id:"cs-6330",module:"changshi",prompt:"通货膨胀率持续为负称为：",options:["滞胀", "通货紧缩", "衰退", "萧条"],answer:1,explanation:"物价总水平持续下跌即通货膨胀率为负，称为通货紧缩。"},{id:"cs-6331",module:"changshi",prompt:"中央银行提高存款准备金率，通常会导致：",options:["市场流动性增加", "市场流动性收紧", "物价上涨", "汇率上升"],answer:1,explanation:"提高存款准备金率使商业银行可贷资金减少，市场流动性收紧，属于紧缩性货币政策。"},{id:"cs-6332",module:"changshi",prompt:"CPI指数上涨通常意味着：",options:["居民消费价格总体下降", "居民消费价格总体上涨", "生产成本下降", "股市上涨"],answer:1,explanation:"CPI即居民消费价格指数，上涨表示居民消费价格总体水平上涨。"},{id:"cs-6333",module:"changshi",prompt:"'需求价格弹性'大意味着：",options:["价格变化对需求量影响小", "价格变化对需求量影响大", "需求不受价格影响", "供给变化大"],answer:1,explanation:"需求价格弹性大表示需求量对价格变化反应敏感，如奢侈品；生活必需品弹性小。"},{id:"cs-6334",module:"changshi",prompt:"完全垄断市场中，厂商是价格的：",options:["接受者", "制定者", "跟随者", "忽略者"],answer:1,explanation:"完全垄断市场中只有一家厂商，它是价格的制定者；完全竞争市场中厂商是价格接受者。"},{id:"cs-6335",module:"changshi",prompt:"'口红效应'指的是：",options:["经济繁荣时奢侈品畅销", "经济不景气时低价消费品销量上升", "化妆品价格持续上涨", "口红供不应求"],answer:1,explanation:"经济下行时人们收入减少，转而购买价格较低的消费品如口红来获得心理慰藉，称为口红效应。"},{id:"cs-6336",module:"changshi",prompt:"我国目前的法定货币发行机构是：",options:["财政部", "中国人民银行", "国有商业银行", "国家开发银行"],answer:1,explanation:"中国人民银行是我国的中央银行，是唯一的人民币发行机构。"},{id:"cs-6337",module:"changshi",prompt:"'边际效用递减'是指：",options:["消费越多总效用越低", "随着消费量增加，每增加一单位消费带来的效用增量减少", "价格越低效用越大", "收入越高消费越少"],answer:1,explanation:"边际效用递减规律指连续消费同一物品时，每增加一单位消费所获得的额外满足感逐渐减少。"},{id:"cs-6338",module:"changshi",prompt:"股票价格与市场利率的一般关系是：",options:["利率上升股价上升", "利率上升股价下跌", "两者无关", "利率下降股价下跌"],answer:1,explanation:"利率上升使企业融资成本增加、资金流向储蓄和债券，股票价格通常下跌。"},{id:"cs-6339",module:"changshi",prompt:"'规模经济'指的是：",options:["企业规模越大亏损越多", "随着产量增加，单位产品平均成本下降", "产量越大利润率越低", "小企业成本更低"],answer:1,explanation:"规模经济指扩大生产规模使单位产品平均成本下降，从而获得成本优势。"},{id:"cs-6340",module:"changshi",prompt:"外汇储备的主要作用不包括：",options:["稳定汇率", "应对国际收支逆差", "增强国际清偿能力", "直接用于国内基建投资"],answer:3,explanation:"外汇储备主要用于稳定汇率、应对国际收支和对外清偿，不能直接用于国内基建。"},{id:"cs-6341",module:"changshi",prompt:"'供给侧改革'的重点任务不包括：",options:["去产能", "去库存", "降成本", "扩大政府直接定价范围"],answer:3,explanation:"供给侧改革重点是'三去一降一补'，即去产能、去库存、去杠杆、降成本、补短板。"},{id:"cs-6342",module:"changshi",prompt:"通货膨胀最直接的影响是：",options:["货币购买力下降", "货币购买力上升", "失业率下降", "收入分配更公平"],answer:0,explanation:"通货膨胀使物价上涨，同样货币能购买的商品减少，即货币购买力下降。"},{id:"cs-6343",module:"changshi",prompt:"'中等收入陷阱'是指：",options:["中等收入群体消费不足", "经济体达到中等收入后长期难以跨入高收入行列", "收入分配平均化", "人均收入下降"],answer:1,explanation:"中等收入陷阱指发展中经济体进入中等收入阶段后，因增长动力不足而长期停滞，难以迈入高收入行列。"},{id:"cs-6344",module:"changshi",prompt:"下列属于紧缩性财政政策的是：",options:["增加政府支出", "减税", "提高税收", "发行国债扩大投资"],answer:2,explanation:"提高税收可减少企业和居民可支配收入，抑制总需求，属于紧缩性财政政策。"},{id:"cs-6345",module:"changshi",prompt:"'绿色GDP'与常规GDP的主要区别在于：",options:["统计范围更小", "扣除资源环境成本后的产出核算", "只统计农业", "只统计服务业"],answer:1,explanation:"绿色GDP在常规GDP基础上扣除资源消耗和环境损害成本，更真实反映经济增长质量。"},{id:"cs-6346",module:"changshi",prompt:"'互联网经济'中的'平台经济'特征是：",options:["双边或多边市场网络效应", "边际成本递增", "完全竞争市场", "零交易成本"],answer:0,explanation:"平台经济连接供需多方，具有网络效应：用户越多平台价值越大，呈现双边市场特征。"},{id:"cs-6347",module:"changshi",prompt:"'普惠金融'的主要目标是：",options:["只为大企业融资", "让更多小微企业和个人获得可负担的金融服务", "提高存款利率", "限制民间借贷"],answer:1,explanation:"普惠金融旨在以可负担的成本为小微企业、农户和低收入人群提供适当有效的金融服务。"},{id:"cs-6348",module:"changshi",prompt:"'数字经济'的核心生产要素是：",options:["土地", "数据", "劳动力", "资本"],answer:1,explanation:"数字经济以数据为关键生产要素，与土地、劳动力、资本、技术并列为生产要素。"},{id:"cs-6349",module:"changshi",prompt:"'供应链金融'主要解决的问题是：",options:["消费者信贷", "中小企业融资难", "外汇管制", "股市波动"],answer:1,explanation:"供应链金融依托核心企业信用和真实贸易背景，为上下游中小企业提供融资支持。"},{id:"cs-6350",module:"changshi",prompt:"'汇率贬值'对本国经济的影响通常是：",options:["出口商品竞争力下降", "出口商品以外币计价更便宜，利于出口", "进口商品更便宜", "资本流入增加"],answer:1,explanation:"本币贬值使出口商品外币价格下降，增强出口竞争力；同时进口商品本币价格上升。"},{id:"cs-6351",module:"changshi",prompt:"'存款保险制度'的保障对象是：",options:["银行本身", "存款人的存款", "理财产品", "贷款企业"],answer:1,explanation:"存款保险制度为存款人在银行的存款提供保障，我国规定单一存款人本息最高偿付50万元。"},{id:"cs-6352",module:"changshi",prompt:"'内循环为主、双循环相互促进'的新发展格局中，'内循环'指的是：",options:["国内大循环", "省内经济循环", "企业内部循环", "资金内部循环"],answer:0,explanation:"内循环指以国内大循环为主体，通过扩大内需、畅通国内生产分配流通消费各环节促进经济发展。"},{id:"cs-6353",module:"changshi",prompt:"'岁寒三友'指的是：",options:["松竹梅", "梅兰菊", "松柏梅", "竹菊兰"],answer:0,explanation:"岁寒三友指松、竹、梅，因三者耐寒，象征坚贞不屈的品格。"},{id:"cs-6354",module:"changshi",prompt:"科举考试中殿试的第一名称为：",options:["状元", "榜眼", "探花", "解元"],answer:0,explanation:"殿试第一名为状元，第二名为榜眼，第三名为探花；乡试第一名为解元。"},{id:"cs-6355",module:"changshi",prompt:"'杏林'在传统文化中代指：",options:["教育界", "医学界", "戏曲界", "农业"],answer:1,explanation:"三国名医董奉治病不收钱，只求种杏树，后以'杏林'代指医界；'杏坛'才代指教育界。"},{id:"cs-6356",module:"changshi",prompt:"我国古代'六亲'中通常不包括：",options:["父", "母", "兄弟", "邻居"],answer:3,explanation:"六亲一般指父、母、兄、弟、妻、子等亲属，邻居不属于六亲。"},{id:"cs-6357",module:"changshi",prompt:"'金榜题名'与下列哪项科举制度直接相关？",options:["殿试放榜", "武举", "察举制", "九品中正制"],answer:0,explanation:"科举殿试后张榜公布录取名单称'金榜'，故考中称'金榜题名'。"},{id:"cs-6358",module:"changshi",prompt:"古代'及笄之年'指女子：",options:["满12岁", "满15岁", "满18岁", "满20岁"],answer:1,explanation:"古代女子15岁行笄礼表示成年，称'及笄之年'；男子20岁行冠礼称'弱冠'。"},{id:"cs-6359",module:"changshi",prompt:"'三教九流'中的'三教'指：",options:["儒、道、佛", "儒、墨、道", "道、法、佛", "儒、法、墨"],answer:0,explanation:"三教指儒教、道教、佛教；九流泛指各学派或社会各行业阶层。"},{id:"cs-6360",module:"changshi",prompt:"我国古代'四大发明'不包括：",options:["造纸术", "印刷术", "火药", "地动仪"],answer:3,explanation:"四大发明为造纸术、印刷术、指南针、火药；地动仪是张衡的发明但不属于四大发明。"},{id:"cs-6361",module:"changshi",prompt:"'连中三元'中的'三元'指：",options:["解元、会元、状元", "状元、榜眼、探花", "秀才、举人、进士", "乡试、会试、殿试"],answer:0,explanation:"科举中乡试、会试、殿试均得第一，分别称解元、会元、状元，合称'连中三元'。"},{id:"cs-6362",module:"changshi",prompt:"'令尊'是对他人什么的尊称？",options:["对方的父亲", "对方的母亲", "对方的儿子", "对方的老师"],answer:0,explanation:"令尊是对对方父亲的敬称，令堂是对对方母亲的敬称。"},{id:"cs-6363",module:"changshi",prompt:"'汗青'在古文中代指：",options:["史册", "汗水", "竹简", "青色染料"],answer:0,explanation:"古代用火烤竹简去湿便于书写，称'汗青'，后引申为史册，如'留取丹心照汗青'。"},{id:"cs-6364",module:"changshi",prompt:"'社稷'中的'社'原指：",options:["土地神", "谷神", "社火", "社会"],answer:0,explanation:"'社'指土地神，'稷'指谷神，社稷合起来代指国家。"},{id:"cs-6365",module:"changshi",prompt:"'桃李满天下'中的'桃李'代指：",options:["学生", "朋友", "亲人", "同僚"],answer:0,explanation:"'桃李'比喻所教的学生，'桃李满天下'形容培养的学生众多。"},{id:"cs-6366",module:"changshi",prompt:"'鸿雁传书'中'鸿雁'在传统文化中代指：",options:["书信", "军队", "爱情", "丰收"],answer:0,explanation:"古人认为鸿雁能传递书信，故以鸿雁代指书信和信使。"},{id:"cs-6367",module:"changshi",prompt:"'东床快婿'典故与哪位书法家有关？",options:["王羲之", "颜真卿", "柳公权", "欧阳询"],answer:0,explanation:"东晋太尉郗鉴选婿，王羲之坦腹东床不以为意，被选中，后以'东床'代指女婿。"},{id:"cs-6368",module:"changshi",prompt:"'洛阳纸贵'的典故源于哪部作品？",options:["《三都赋》", "《二京赋》", "《两都赋》", "《子虚赋》"],answer:0,explanation:"西晋左思作《三都赋》，洛阳人竞相传抄，一时纸价上涨，后以'洛阳纸贵'形容作品风行。"},{id:"cs-6369",module:"changshi",prompt:"'破釜沉舟'的典故发生在哪场战役？",options:["巨鹿之战", "赤壁之战", "官渡之战", "淝水之战"],answer:0,explanation:"秦末项羽在巨鹿之战中砸锅沉船，表示决一死战，大破秦军。"},{id:"cs-6370",module:"changshi",prompt:"'纸上谈兵'的典故主人公是：",options:["赵括", "廉颇", "李牧", "白起"],answer:0,explanation:"战国时赵国名将赵奢之子赵括熟读兵书但缺乏实战经验，长平之战大败，后以'纸上谈兵'讥讽空谈理论。"},{id:"cs-6371",module:"changshi",prompt:"'卧薪尝胆'的主人公是：",options:["勾践", "夫差", "伍子胥", "范蠡"],answer:0,explanation:"春秋末期越王勾践战败后睡柴草尝苦胆以励志，最终灭吴复国。"},{id:"cs-6372",module:"changshi",prompt:"'指鹿为马'的典故人物是：",options:["赵高", "李斯", "吕不韦", "嫪毐"],answer:0,explanation:"秦朝宦官赵高牵鹿称马试探朝臣，后以'指鹿为马'比喻颠倒黑白。"},{id:"cs-6373",module:"changshi",prompt:"'四面楚歌'的典故主人公是：",options:["项羽", "刘邦", "韩信", "张良"],answer:0,explanation:"楚汉相争末期，项羽被围垓下，夜闻四面楚歌，军心涣散，最终自刎乌江。"},{id:"cs-6374",module:"changshi",prompt:"'三顾茅庐'请出诸葛亮的是：",options:["刘备", "曹操", "孙权", "刘表"],answer:0,explanation:"东汉末年刘备三次到隆中拜访诸葛亮，请其出山辅佐，后以'三顾茅庐'形容诚心求贤。"},{id:"cs-6375",module:"changshi",prompt:"世界上人口最多的洲是：",options:["非洲", "亚洲", "欧洲", "南美洲"],answer:1,explanation:"亚洲人口约占世界总人口的60%，是世界人口最多的洲。"},{id:"cs-6376",module:"changshi",prompt:"世界上火山最多的国家是：",options:["日本", "印度尼西亚", "智利", "美国"],answer:1,explanation:"印度尼西亚位于环太平洋火山地震带，有活火山100多座，是世界火山最多的国家。"},{id:"cs-6377",module:"changshi",prompt:"世界上国土最狭长的国家是：",options:["智利", "挪威", "越南", "意大利"],answer:0,explanation:"智利南北长约4300公里，东西宽仅100-400公里，是世界最狭长的国家。"},{id:"cs-6378",module:"changshi",prompt:"世界上人口密度最大的大洲是：",options:["亚洲", "欧洲", "非洲", "大洋洲"],answer:1,explanation:"欧洲面积较小而人口较多，是世界人口密度最大的洲。"},{id:"cs-6379",module:"changshi",prompt:"世界著名的'风城'是：",options:["惠灵顿", "雷克雅未克", "芝加哥", "爱丁堡"],answer:0,explanation:"新西兰首都惠灵顿常年多风，被称为'风城'。"},{id:"cs-6380",module:"changshi",prompt:"被称为'千岛之国'的是：",options:["印度尼西亚", "菲律宾", "日本", "挪威"],answer:0,explanation:"印度尼西亚由17000多个岛屿组成，被称为'千岛之国'。"},{id:"cs-6381",module:"changshi",prompt:"被称为'咖啡王国'的国家是：",options:["巴西", "哥伦比亚", "埃塞俄比亚", "越南"],answer:0,explanation:"巴西是世界最大的咖啡生产国和出口国，被称为'咖啡王国'。"},{id:"cs-6382",module:"changshi",prompt:"世界上跨经度最广的大洋是：",options:["太平洋", "大西洋", "印度洋", "北冰洋"],answer:3,explanation:"北冰洋围绕北极点，跨越所有经度，是世界上跨经度最广的大洋。"},{id:"cs-6383",module:"changshi",prompt:"被称为'黄金水道'的河流是：",options:["长江", "莱茵河", "密西西比河", "尼罗河"],answer:0,explanation:"长江航运价值高，干流通航里程长，货运量居世界内河前列，被称为'黄金水道'。"},{id:"cs-6384",module:"changshi",prompt:"世界上最大的盆地是：",options:["刚果盆地", "塔里木盆地", "准噶尔盆地", "乍得盆地"],answer:0,explanation:"刚果盆地位于非洲中部，面积约337万平方公里，是世界最大的盆地。"},{id:"cs-6385",module:"changshi",prompt:"世界上面积最大的热带雨林分布在：",options:["亚马逊平原", "刚果盆地", "东南亚", "印度西部"],answer:0,explanation:"亚马逊平原分布着世界面积最大的热带雨林，被称为'地球之肺'。"},{id:"cs-6386",module:"changshi",prompt:"世界上最大的咸水湖群所在的大洲是：",options:["亚洲", "欧洲", "非洲", "北美洲"],answer:0,explanation:"里海横跨亚洲和欧洲，是世界最大的咸水湖，主要位于亚洲一侧。"},{id:"cs-6387",module:"changshi",prompt:"被称为'高原大陆'的大洲是：",options:["非洲", "亚洲", "南美洲", "大洋洲"],answer:0,explanation:"非洲大陆地形以高原为主，海拔较高，被称为'高原大陆'。"},{id:"cs-6388",module:"changshi",prompt:"世界上唯一地跨亚洲和大洋洲的国家是：",options:["印度尼西亚", "巴布亚新几内亚", "澳大利亚", "菲律宾"],answer:0,explanation:"印度尼西亚领土包括亚洲的加里曼丹岛大部分和大洋洲的伊里安查亚地区，地跨两洲。"});
